window.DB_NODES.push(
// ── 古典分层 ──
{id:"marx_class",aka:"马克思 阶级剥削 剩余价值 资本论",domains:["money","work"],lever:0,cn:"阶级剥削论",en:"Class & Exploitation",scholar:"Karl Marx",work:"《资本论》Das Kapital",year:"1867",disc:"soc",school:"古典分层",core:"生产资料占有决定位置，剥削关系在劳动过程中自我再生产。",detail:"马克思的核心不是「穷人很惨」而是「剥削是结构性位置」：资本家占有生产资料，工人只能出售劳动力，而劳动力这个商品的特殊之处在于它能创造超出自身价值的价值——剩余价值在劳动过程中被无偿占有，还透过工资形式被遮蔽成「公平交换」。所以剥削不需要坏老板，它是匿名的、自我再生产的关系：今天的剩余变成明天的资本，阶级位置随之复制。实证上，两极化预言被二十世纪中产阶级膨胀部分证伪，但「剥削关系」的问题意识撑起了整个冲突论传统。图谱中它以谱系边连「阶级位置图式」——Wright 把不可直接测量的剥削概念操作化成所有权×权威×技能的矩阵；又以张力边接「功能主义分层」——Davis & Moore 说不平等是功能必需的诱因装置，冲突论说它是权力战利品，对同一份收入分布给出相反的合法性判决。边界：别把剥削当道德指控用，它是技术概念；但劳动价值论前提在现代经济学里站不住，剥削概念需要重构。",links:[{t:"Penguin Classics《Capital》卷一官方页",u:"https://www.penguinrandomhouse.com/books/261069/capital-by-karl-marx-translated-by-ben-fowkes-introduction-by-ernest-mandel/"}]},
{id:"weber_class",aka:"韦伯 阶级地位政党 多维分层",domains:["money","work","mobility"],lever:0,cn:"阶级·地位·政党",en:"Class, Status, Party",scholar:"Max Weber",work:"《经济与社会》",year:"1922",disc:"soc",school:"古典分层",core:"市场机会定阶级位置，生活方式与荣誉定地位群体边界，三维分层。",detail:"韦伯把马克思的单轴分层拆成三个独立维度：阶级由市场机会（收入、技能、议价能力）决定，地位群体由生活方式与社会荣誉划界，政党是权力领域的组织化竞逐。关键在于三轴可以错位——暴发户有钱无地位，没落贵族反之——这让韦伯比马克思更能处理「品味」与「声望」这类非经济支配形式。他还埋下「社会封闭」概念：地位群体靠排除外人（婚姻、教育、社交规则）来垄断稀缺机会。实证传统上，韦伯路线催生了 Goldthorpe 的 Nuffield 阶级图式等主流阶层实证研究。图谱中它以谱系边连「社会封闭」——Parkin 把韦伯散见的封闭段落系统化为「排斥」（上对下关门）与「篡夺」（下对上推门）双机制。边界：三轴是分析维度而非三种真实群体，常见误用是把「地位」简化成「消费品味」而漏掉背后的垄断机制；也有批评说多维模型把冲突稀释成分类学。",links:[{t:"UC Press《Economy and Society》",u:"https://www.ucpress.edu/books/economy-and-society-2/paper"}]},
{id:"durkheim_division",aka:"涂尔干 迪尔凯姆 社会分工论",domains:["work","relation"],lever:0,cn:"分工与有机团结",en:"Division of Labour",scholar:"Émile Durkheim",work:"《社会分工论》",year:"1893",disc:"soc",school:"古典分层",core:"分工使阶层互赖整合；'被迫分工'导致病态整合失败。",detail:"涂尔干问的是：分工越细、个人越不同，社会怎么还不散架？答案是分工创造「有机团结」——像器官互赖，你我职业不同所以彼此需要，这种功能性依赖本身就是道德整合的来源，不再需要共享整套价值观。但他留了个常被忽略的关键例外：当分工是「被迫的」——职位分配与能力错配、外部条件不平等——团结就失败，产生失范。这个「病态分工」注脚正是理解阶级不满的涂尔干式入口：问题不在分化本身，而在分化的「自发性」被出身扭曲。图谱中它以谱系边连「自杀论/失范」——同一个著作计划的延伸：《自杀论》把失范发展成完整诊断，规范真空时欲望无限扩张。边界：有机团结是理想型，现代整合也靠权力与强制，涂尔干低估了支配面向；别把它读成分工万岁的辩护词，「被迫分工」恰恰是内建的批判版本。",links:[{t:"Bloomsbury《The Division of Labour in Society》",u:"https://www.bloomsbury.com/uk/durkheim-the-division-of-labour-in-society-9781137031822/"}]},
{id:"davismoore",aka:"戴维斯 穆尔 功能主义分层",domains:["work","money"],lever:0,cn:"功能主义分层",en:"Functionalist Stratification",scholar:"Davis & Moore",work:"Some Principles of Stratification",year:"1945",disc:"soc",school:"古典分层",core:"以不等报酬吸引稀缺人才充任要职——分层是功能必需（被Tumin批判为权力产物）。",detail:"Davis & Moore 的命题干脆俐落：有些职位功能上更重要、合格人才更稀缺，社会必须用不平等报酬把最好的人引到最关键的位置——所以分层不是剥削而是「无意识进化出的必要装置」。这篇 1945 年的八页短文是功能主义分层的标准陈述，也是社会学史上最被批评的论文之一：Tumin 1953 年逐点反驳——「功能重要性」如何独立于报酬测量（先知 vs 清洁工）？为什么诱因非得是收入而非荣誉？不平等本身会不会扭曲人才评估？图谱中它以张力边直指「阶级剥削论」——功能必需 vs 权力产物，是解释同一份不平等光谱的两个本体论：一个把阶层看成社会的价格信号，一个看成支配的累积结果。边界：它把现状当证据的循环论证嫌疑最重；但它逼出了所有反方绕不开的问题——如果分层真没必要，如何解释它在每个复杂社会的普遍性？",links:[{t:"ASR 1945 原文 (JSTOR DOI)",u:"https://doi.org/10.2307/2085643"}]},
{id:"wright_class",aka:"赖特 阶级位置 矛盾的阶级位置",domains:["work","money","mobility"],lever:0,cn:"阶级位置图式",en:"Class Schema",scholar:"Erik Olin Wright",work:"Classes / Class Counts",year:"1985/1997",disc:"soc",school:"古典分层",core:"剥削轴叠加权威与技能维度，定位'矛盾阶级位置'——中产的操作化定义尝试。",detail:"Wright 接手的是马克思留下的尴尬题：中产阶级在哪？他的答案是把「剥削」拆成三条轴线——生产资料所有权、组织权威、稀缺技能——三者可以交叉补偿，于是经理与专家落在「矛盾的阶级位置」：他们凭权威与技能分享剩余（剥削者面向），却无所有权（被剥削面向）。这让中产阶级不再是边界模糊的剩余范畴，而是有明确矛盾利益的结构位置。《Class Counts》用跨国调查把图式跑成实证计划——阶级位置对收入与意识形态的预测比职业类别更强，是马克思主义阶级分析少见的大样本操作。图谱中它以谱系边接自「阶级剥削论」——把剥削从形上命题操作化成可测量、可复查的位置矩阵。边界：把剥削「去关系化」成格子的批评一直存在（Goldthorpe 派质疑其对流动与阶级行动的解释力）；Wright 晚年也承认技能轴混入了租金机制，转向更宽的机会剥削框架。",links:[{t:"Cambridge Core《Class Counts》DOI",u:"https://doi.org/10.1017/CBO9780511488917"}]},
{id:"parkin_closure",aka:"帕金 社会封闭 排斥 篡夺",domains:["mobility","work","money"],lever:0,cn:"社会封闭",en:"Social Closure",scholar:"Frank Parkin",work:"Marxism and Class Theory",year:"1979",disc:"soc",school:"古典分层",core:"新韦伯派：支配靠排斥(exclusion)与篡夺(usurpation)双重封闭机制维系。",detail:"Parkin 的社会封闭是新韦伯派的核心武器：支配不必诉诸所有权，只要能把外人挡在稀缺资源门外就行。他把封闭拆成两个方向相反的机制——「排斥」是优势群体向下关门（证照、语言、学历、裙带），「篡夺」是劣势群体的集体推门（工会、抗争运动）。这对概念把阶级斗争改写成「门票战争」：不平等的核心不在剥削关系，而在谁能设置边界、谁被迫绕路。图谱中它以谱系边接自「阶级·地位·政党」——韦伯在《经济与社会》里散见的封闭段落被 Parkin 系统化成双机制模型；又以耦合边接「教育同质婚配」——教育筛选出的配偶匹配恰恰行使著婚姻场域的社会封闭，只是门做成了爱情的形状。边界：封闭理论强在描述「守门」而非解释门内外收益差从何而来，与剥削论是互补而非替代；常被误用为凡群体界线皆封闭，但 Parkin 要求的是对稀缺资源获取的排除，纯社交圈不算。",links:[{t:"Columbia UP《Marxism and Class Theory》",u:"https://cup.columbia.edu/book/marxism-and-class-theory/9780231048811/"}]},
// ── 地位获得/流动 ──
{id:"turner_mobility",aka:"特纳 赞助式流动 竞争式流动",stages:["s2","s3"],domains:["mobility","work"],lever:0,cn:"赞助/竞争流动",en:"Sponsored & Contest Mobility",scholar:"Ralph Turner",work:"Sponsored and Contest Mobility",year:"1960",disc:"soc",school:"流动经验学派",core:"英制=精英挑选受控上升(赞助)，美制=开放竞争自我驱动——制度预设了流动通道类型。",detail:"Turner 比较英美，发现两种制度化的流动意识形态：英制是「赞助流动」——像俱乐部挑选成员，精英在早期就锁定少数人受控上升，输家安心留在原地因为游戏本来就没对他们开放；美制是「竞争流动」——人人皆可参赛、规则公开，赢家自我驱动，输家只能怪自己。重点是制度不只提供通道，还供给整套合理化叙事：赞助制下输家不羞耻，竞争制下每个失败都是个人判决。图谱中它以谱系边连「地位获得模型」——通道类型学被 Blau & Duncan 翻译成可测的路径系数；以张力边连「志向持平」——竞争流动承诺的开放，被 MacLeod 的 Hallway Hangers 证明是按阶级配给的幻觉；耦合边来自两方：「血统/精英招聘」（文化匹配招聘正是赞助制在雇用端的当代兑现）与「弱关系的力量」（工作资讯的网络通道是流动的微观机械面）。边界：二型是理想型，真实制度混杂两者；概念对解释美国教育民间信仰仍有惊人寿命。",links:[{t:"ASR 1960 原文 (JSTOR DOI)",u:"https://doi.org/10.2307/2089982"}]},
{id:"blauduncan",aka:"布劳 邓肯 地位获得 美国职业结构",stages:["s2","s3"],domains:["mobility","work"],lever:0,cn:"地位获得模型",en:"Status Attainment Model",scholar:"Blau & Duncan",work:"The American Occupational Structure",year:"1967",disc:"soc",school:"流动经验学派",core:"父职→教育→初职→现职的路径系数，首次量化分解代际传递强度。",detail:"Blau & Duncan 把「你是怎么走到今天位置的」拆成一条可计量的因果链：父亲职业与教育→自己的教育→第一份工作→当前职业，用 1962 年两万人调查数据跑出路径系数——父亲对儿子地位的直接效应其实小，大半经教育与初职间接传递。这是社会学史上第一次把代际传递量化分解，地位获得研究（Wisconsin 学派）由此成为范式，也把美国写成「高开放度」的基准线——后来所有流动性比较都以它为座标原点。图谱中它以谱系边接自「赞助/竞争流动」——Turner 的制度通道类型被翻成统计路径；以张力边被「交叉性/统治矩阵」挑战——单轴加性模型（种族+阶级+性别各自独立效应）在交叉性批判下显得幼稚：位置不是变数相加而是相互构成。边界：路径系数是描述性关联而非因果识别，省略所有未观测择优机制；OCG 只涵盖男性，且职业声望这个因变量本身带著 1960 年代的阶级想像。",links:[{t:"Stanford Center on Poverty & Inequality 书目",u:"https://inequality.stanford.edu/publications/media/details/american-occupational-structure"}]},
{id:"boudon",aka:"布东 布顿 初级效应 次级效应",stages:["s1","s2"],domains:["mobility","money"],lever:0,cn:"初/次级效应",en:"Primary & Secondary Effects",scholar:"Raymond Boudon",work:"L'inégalité des chances",year:"1973",disc:"soc",school:"流动经验学派",core:"阶级差=成绩差(初级)+同成绩下的选择差(次级)——软锁死的形式化：只需决策点期望函数不同。",detail:"Boudon 把教育不平等拆成两段：初级效应是成绩差——阶级间学业表现的客观差距；次级效应是「同样成绩、不同选择」——同分数的两个孩子，劳工子弟选职业轨、中产子弟选大学。他的形式化证明很犀利：不需要文化资本、不需要价值观差异，只要不同阶级对升学成本/收益/机率的期望函数不同，就会产生系统性选择差。这是「软锁死」的最小充分模型——门没锁，是每个人在门前算出了不同答案。图谱中它以谱系边连「相对风险厌恶模型」——Breen & Goldthorpe 把次级效应改写成避免向下流动的风险决策；以张力边连「惯习·场域·资本」（同一份数据：理性校准 vs 文化匹配的两种本体论）与「消逝的美国梦/机会地图」（描述性路径系数 vs 搬迁实验的因果识别，方法论断裂）。边界：次级效应把偏好当外生，无法解释期望函数本身怎么被结构形塑——这正是布迪厄派反击的缺口。",links:[{t:"Google Books《Education, Opportunity, and Social Inequality》",u:"https://books.google.com/books/about/Education_Opportunity_and_Social_Inequal.html?id=qJWdAAAAMAAJ"}]},
{id:"breen_rat",aka:"布林 戈德索普 相对风险规避",stages:["s1","s2"],domains:["mobility","money"],lever:0,cn:"相对风险厌恶模型",en:"Relative Risk Aversion",scholar:"Breen & Goldthorpe",work:"Explaining Educational Differentials",year:"1997",disc:"soc",school:"流动经验学派",core:"次级效应的理性选择形式化：避免向下流动的风险厌恶驱动升学决策差异。",detail:"Breen & Goldthorpe 把 Boudon 的次级效应塞进理性行动的形式模型：家庭在升学决策点上评估的不只是期望值，还有失败的风险——而「向下流动」的威胁对不同阶级不对称。中产家庭的孩子留在父母阶级之下是灾难，所以几乎无条件升学；劳工家庭把中学毕业当达标，继续读反而是高风险赌注。模型漂亮地同时解释三个现象：入学率整体扩张、阶级差异几乎不动、性别差异快速消失——一个微观决策逻辑推出整个宏观趋势。图谱中它以谱系边接自「初/次级效应」——把 Boudon 的概念命题变成可检验的微观决策理论；以耦合边接「文化资本批评」——Goldthorpe 同时是 RRA 作者和布迪厄最凶的批评者，理性选择阵营的火力点与替代方案是配套生产的。边界：把风险厌恶当外生心理参数，批评者说这只是把文化资本换了名字；且对劳工家庭为何低估成功机率的期望形成过程著墨少——这正是后来行为经济学在补的洞。",links:[{t:"Rationality and Society 原文 DOI",u:"https://doi.org/10.1177/104346397009003002"}]},
{id:"tilly_durable",aka:"蒂利 持久不平等 机会囤积",domains:["work","money","mobility"],lever:0,cn:"持久不平等",en:"Durable Inequality",scholar:"Charles Tilly",work:"Durable Inequality",year:"1998",disc:"soc",school:"流动经验学派",core:"剥削与机会囤积经类别配对(种族/性别/文凭)在组织边界上制度化延续。",detail:"Tilly 问：为什么不平等总以「成对类别」的形式出现——男/女、白人/黑人、公民/外来者、有文凭/没文凭？他的机制论答案：组织在解决实际问题时发现「类别配对」很好用——把高酬劳内部圈与低酬劳外部圈用某条界线分开，「剥削」（内圈占有外圈劳动成果）与「机会囤积」（内圈垄断增值机会）就沿界线被制度化。不平等持久不是因为态度顽固，而是因为两边都依赖这个安排运转——连受损方也围绕它组织了生活，改变成本对所有人都不对称。图谱中它以谱系边连「机会囤积」——Reeves 把 Tilly 的机制名词直接拿去诊断上中产 20% 的育儿实践，等于是这个框架的应用篇。边界：Tilly 的解释是机制故事而非可证伪模型，各案例共通逻辑强但预测力弱；它解释「不平等如何被维持」好过解释「为何是此类别而非彼类别被选中」——类别的选择本身仍需历史叙事补上。",links:[{t:"UC Press《Durable Inequality》",u:"https://www.ucpress.edu/books/durable-inequality/paper"}]},
{id:"reeves_hoarding",aka:"里维斯 梦想囤积者 机会囤积",stages:["s1","s2","s3"],classes:["c2"],domains:["family","mobility","money"],lever:0,cn:"机会囤积",en:"Opportunity Hoarding",scholar:"Richard Reeves",work:"Dream Hoarders",year:"2017",disc:"soc",school:"流动经验学派",core:"上中20%以学区、实习、录取偏好把机会囤积给子女——中产的结构护城河。",detail:"Reeves 把火力从顶层 1% 转向上中产 20%：真正拉开差距的不是巨富，而是专业管理阶级把「机会」变成可继承资产的日常操作——学区房、无薪实习、校友子女优先录取、职业证照，每个看起来无害的「为孩子好」累加起来就是一道结构护城河。他借用 Tilly 的机会囤积概念但落到中产微观实践：囤积不需要密谋，只需要市场让好位置可以被购买、育儿焦虑让人人都买。图谱中它以谱系边接自「持久不平等」——Tilly 在组织层面讲的机制被 Reeves 翻译成育儿政治诊断；以耦合边接「鼠崽竞赛」——Ramey 的育儿军备竞赛正是机会囤积的日常执行版本，投入强度随升学竞争烈度调节。边界：批评者指出 20% 切法把中产上层过度同质化，且学区效应的美国特例性强；把合法育儿投资叫「囤积」有道德化过头之嫌——但 Reeves 的回应是，正是「合法」让它隐形。",links:[{t:"Brookings《Dream Hoarders》",u:"https://www.brookings.edu/books/dream-hoarders/"}]},
{id:"goldthorpe_crit",aka:"戈德索普 高德索普 文化资本批判",stages:["s1","s2"],domains:["mobility"],lever:0,cn:"文化资本批评",en:"Cultural Capital Critique",scholar:"John Goldthorpe",work:"Cultural Capital: A Critical Review",year:"2007",disc:"soc",school:"流动经验学派",core:"理性选择派反击：'文化资本'不可测、循环论证，对教育不平等经验解释力弱。",detail:"Goldthorpe 2007 年这篇 Sociologica 评论是理性选择阵营对布迪厄最系统的公开讨伐：「文化资本」在文献中至少有四种用法，而它们共享同一个方法论硬伤——用结果反推概念存在（劳工子弟学不好→缺文化资本→所以学不好），循环论证且几乎不可证伪。他进一步指出，控制成绩与能力后，文化资本对教育不平等的可测量解释力其实很小，大部分差异走的是阶级资源与风险决策的路径。图谱中它以张力边直指「惯习·场域·资本」——两阵营争的是同一份教育不平等数据的解释权：文化机制 vs 决策机制；以耦合边连「相对风险厌恶模型」——Goldthorpe 与 Breen 是同一个 Nuffield 阵营，批评火力与替代方案配套生产。边界：这篇批评打的是「文化资本」这个测量传统，而非布迪厄全部理论（他对资本可转换其实借用不少）；Lareau 派回应说量表本来就测不到「制度确认」这种关系性机制——争论至今未决。",links:[{t:"Sociologica 原文 DOI",u:"https://doi.org/10.2383/24755"}]},
// ── 布迪厄学派 ──
{id:"bourdieu",aka:"布迪厄 布尔迪厄 布赫迪厄",domains:["mobility","money","relation"],lever:0,cn:"惯习·场域·资本",en:"Habitus / Field / Capital",scholar:"Pierre Bourdieu",work:"《再生产》1970 /《区分》1979",year:"1970/1979",disc:"soc",school:"布迪厄学派",core:"被结构化的结构又作为结构化结构起作用；教育把文化资本差译成'天赋'差完成再生产。",ref:"另见 Pascalian Meditations(hysteresis)、《世界的苦难》1993",detail:"布迪厄的三件套是整张图谱的地基：惯习是「被结构化的结构，又作为结构化的结构起作用」——童年位置沉淀为知觉与期望的生成器，让人自动想要「配得上」的东西；场域是有自己入场券与回报率的位置竞技场；资本有四种形态且可相互兑换。教育系统的魔术在于把文化资本差距翻译成「天赋」差距：家中继承的被登记为个人成就的，符号暴力于是完成——被支配者也承认这把尺。图谱中它是边最多的节点：上游谱系来自「阿尔及利亚/hysteresis源」（卡比尔田野的撕裂经验是惯习概念的民族志根），下游放出「道德-文化边界」（Lamont 把区隔双向化）、「回归故里」（Eribon 把 hysteresis 写成自传）、「特权/从容」（Khan 用从容重写精英惯习）；耦合接「协作培养/自然成长」（Lareau 是惯习养成的民族志兑现）、「血统/精英招聘」（文化资本被洗白成文化匹配）、「严肃人/情境中的自由」（Beauvoir 的压迫维度与惯习互补）；张力对手最多——「学做工/反学校文化」（Willis 的抵抗含未被收编的能动性，同时也是产出边：抵抗恰被再生产回收成体力劳动的同意）、「初/次级效应」「文化资本批评」「文化工具箱」「生命历程五原则」「阶级穿越者」「坏信仰/被判自由」「意义意志/存在真空」「存在人类学」——整个结构 vs 能动性争论都以它为靶心。边界：最大误读是决定论——惯习是倾向非宿命，hysteresis 恰恰证明它可错位。",links:[{t:"Routledge《Distinction》",u:"https://www.routledge.com/Distinction-A-Social-Critique-of-the-Judgement-of-Taste/Bourdieu/p/book/9780415567886"}]},
{id:"lamont",aka:"拉蒙特 符号边界 道德边界",domains:["relation","meaning"],lever:0,cn:"道德-文化边界",en:"Boundary Work",scholar:"Michèle Lamont",work:"Money, Morals, and Manners / Dignity of Working Men",year:"1992/2000",disc:"soc",school:"布迪厄学派",core:"阶级以道德/品味划界；工人用尊严话语反向评价上层——区隔的双向版本。",detail:"Lamont 把布迪厄的区隔从单向改成双向：不只上层用品味向下划界，工人也主动用道德词汇向上划界——《工作的尊严》里美国劳工把自己定位为「自律、顾家、诚实」的人，反过来评价上层为「空洞、自恋、失去分寸」。她在《钱、道德、品味》中先解剖上中产的三类边界（社经/道德/文化），发现美国人重社经、法国人重文化。核心概念「符号边界」：群体成员资格是划线划出来的，而道德词汇是弱势者手里为数不多的划线工具。图谱中它以谱系边接自「惯习·场域·资本」——把 Bourdieu 的区隔补上受评价方的视角；耦合边接「阶级隐痛」（工人的尊严话语=隐性伤害的当代形态）、「承认理论」（道德边界=承认秩序的微观机制）、「拟剧论/污名」（印象管理×道德划界的互动接口）。边界：访谈法抓到的是「说得出口的边界」，会低估实作层面的品味歧视；样本限于男性劳工，性别与家庭场域的边界工作需另案处理。",links:[{t:"Michèle Lamont 官方著作列表",u:"http://www.michelelamont.org/books"}]},
{id:"swidler",aka:"斯威德勒 文化工具箱",domains:["meaning","relation"],lever:1,cn:"文化工具箱",en:"Culture as Toolkit",scholar:"Ann Swidler",work:"Culture in Action",year:"1986",disc:"soc",school:"布迪厄学派",core:"文化不是价值指南而是剧目(repertoire)库——对惯习决定论的主要修正。",detail:"Swidler 1986 年这篇 ASR 把文化研究的主流范式翻了个面：从 Parsons 到早期 Bourdieu 的模型都假设文化透过「内化价值观」指导行动，但她指出行动者很少照价值观走——文化更像一个「工具箱」：一堆习惯、技能、风格的剧目库，人从中组装「行动策略」。在稳定时期文化提供可组装的资源；在动荡时期反而是意识形态直接接管，但哪种意识形态存活由结构机会决定。这篇文章为「文化如何因果作用」提供了可研究的机制版本，是美国文化社会学的奠基文。图谱中它以张力边直指「惯习·场域·资本」——工具箱 vs 惯习：行动者是剧目库的装配者，不是结构的执行器，这是对文化决定论最有力的内部修正。边界：批评者认为工具箱低估了非话语层的体化文化（Swidler 后来自己也补上实作维度）；且「策略」概念易滑向过度自愿主义——忘记工具箱本身也是阶级配给的。",links:[{t:"ASR 1986 原文 (JSTOR DOI)",u:"https://doi.org/10.2307/2095521"}]},
{id:"eribon",aka:"埃里蓬 回归故里",domains:["mobility","meaning"],lever:0,cn:"回归故里",en:"Returning to Reims",scholar:"Didier Eribon",work:"Retour à Reims",year:"2009",disc:"soc",school:"布迪厄学派",core:"阶级叛徒的自我民族志：上升者在两个世界间撕裂，hysteresis的身体自传。",detail:"Eribon 的回忆录是「阶级叛徒」的自我民族志：一个工人家庭出身的同志知识分子回到兰斯，发现自己当年逃离的不只是恐同，还有整个阶级世界——而学术生涯的成功恰恰以持续掩盖出身为代价。他用布迪厄的概念解剖自己的人生：学校把他「选中」也就把他从原生世界连根拔起，hysteresis（惯习滞后）在这里不是术语而是撕裂的体感——两个世界都回不去。书中还分析了他家族从共产党转投国民阵线的投票史，把阶级分析接到当代政治。图谱中它以谱系边接自「惯习·场域·资本」（批判性继承：羞耻是体感而非单纯习性成分），又以谱系边连「阶级穿越者」——Jaquet 把 Eribon 式的穿越经验哲学化为 complexion。边界：单一自传的普遍性靠读者共鸣而非推论保证；Eribon 的写作介于社会学与文学之间，批评者说他借了社会学权威却不承担其证据标准——但也有人认为这正是它作为方法创新的地方。",links:[{t:"MIT Press《Returning to Reims》",u:"https://mitpress.mit.edu/9781584351238/returning-to-reims/"}]},
// ── 教育社会学批判线 ──
{id:"bowlesgintis",aka:"鲍尔斯 金蒂斯 对应原理 资本主义美国的学校教育",stages:["s1","s2"],domains:["work","mobility"],lever:0,cn:"对应原理",en:"Correspondence Principle",scholar:"Bowles & Gintis",work:"Schooling in Capitalist America",year:"1976",disc:"soc",school:"教育批判线",core:"学校的权威结构对应工厂等级制，批量复制阶级化劳动人格。",detail:"Bowles & Gintis 的「对应原理」是新马克思教育社会学的旗舰命题：学校表面教知识，真正量产的是劳动人格——学校的权威结构（钟点、考核、等级、服从）在形式上对应工厂的等级制，不同阶级背景的学生被分流到不同学校与轨道，批量复制出各自对口的顺从度与自我期待。他们用数据证明教育程度对收入的效应主要不是透过认知技能，而是透过非认知的顺从性——学校是阶级再生产的训练场。这本书 1976 年造成轰动，也立刻被批评太功能主义：资本家像编剧一样安排一切，那学生去哪了？图谱中它以谱系边连「学做工/反学校文化」——Willis 正是补上这个缺口的人：他给了对应原理缺失的能动者，却发现能动性恰恰完成再生产，结局比对应原理更悲观。边界：「对应」在资历结构高度同构的美国之外较弱；它解释再生产强于解释变迁，无法处理教育改革与矛盾空间。",links:[{t:"Haymarket《Schooling in Capitalist America》",u:"https://www.haymarketbooks.org/books/269-schooling-in-capitalist-america"}]},
{id:"bernstein",aka:"伯恩斯坦 限定编码 精致编码",stages:["s1","s2"],domains:["family","meaning","mobility"],lever:0,cn:"语言编码",en:"Linguistic Codes",scholar:"Basil Bernstein",work:"Class, Codes and Control",year:"1971",disc:"soc",school:"教育批判线",core:"限定编码(情境依赖)vs精致编码(去情境化)；学校以精致编码运作→劳工子弟结构性劣势。",detail:"Bernstein 把阶级不平等塞进语言的微观结构：限定编码依赖共享情境（在场者心照不宣、意义靠脉络补完），精致编码则去情境化、把意义明确说出来。劳工家庭的语言生态偏向前者，学校制度却只以后者运作——于是「听不懂」被登记成「不聪明」，编码错配在入学第一天就开始收利息。注意他反复强调：限定编码不是缺陷语言，是不同形态的意义组织，补偿教育那种「修补穷孩子语言」的路线恰恰搞错了机制。图谱中它的耦合网很实：连「学做工/反学校文化」（编码错配是反学校认同的语言层底因）、「协作培养/自然成长」（限定↔自然成长、精致↔协作培养的经典配对）、「言说的方式」（Heath 三社区民族志提供了编码差异的实作底稿）、「稀缺认知税」（带宽被占用削弱即兴整合能力——稀缺的语言面）。边界：1970 年代被误读成劳工语言贫乏论掀起论战，Bernstein 本人反对 deficit 解读；编码双分法略糙，当代语言社会学已细化为 register 的连续谱。",links:[{t:"Google Books《Class, Codes and Control》Vol.1",u:"https://books.google.com/books/about/Class_Codes_and_Control_Theoretical_stud.html?id=MwRiAAAAMAAJ"},{t:"ERIC 书目记录",u:"https://eric.ed.gov/?id=ED101021"}]},
{id:"willis",aka:"威利斯 学做工 反学校文化",stages:["s2"],classes:["c1"],domains:["work","mobility","meaning"],lever:0,gender:"m",cn:"学做工/反学校文化",en:"Learning to Labour",scholar:"Paul Willis",work:"Learning to Labour",year:"1977",disc:"soc",school:"教育批判线",core:"'部分洞察'看穿文凭许诺却以颂扬体力/男性气概自我安插回劳工位置——抵抗即再生产。",ref:"样本警告:12名白人劳工子弟男性、一所中部学校——推广需谨慎",detail:"Willis 跟了 12 个「lads」最后两年学校加一年工厂，发现反学校文化含有「部分洞察」：这些小子看穿文凭承诺的空洞（多数人本来就去工厂），但他们用颂扬体力、男性气概与「动手做」来回应，结果亲手把自己安插回劳工位置——抵抗恰恰完成了再生产，而且比顺从更稳固因为它是自选的。「部分」是关键：洞察到结构，却以另一种意识形态（性别分工、脑力/体力对立）接住，于是批判能量被安全排放。图谱中它的谱系网最密：上游接「对应原理」（补上 Bowles & Gintis 缺的主体），下游生出「抵抗理论」（Giroux 把抵抗升格为批判潜能）与「志向持平」（MacLeod 移植到美国公屋+种族维度）；耦合接「语言编码」（错配体验的底因）、「道义经济/弱者武器」（日常抵抗×反学校文化两型）、「结构紧张/失范类型」（创新/退却/反叛=反学校文化的适应类型）；对「惯习·场域·资本」同时是张力（能动性没被收编）与产出（抵抗成为再生产机制本身）。边界：样本极小且全为白人男性，文件自带推广警告；「部分洞察」几乎不可证伪——任何抵抗都可被读成「不够部分」。",links:[{t:"Routledge 电子书 DOI",u:"https://doi.org/10.4324/9781351218788"}]},
{id:"giroux",aka:"吉鲁 抵抗理论 批判教育学",stages:["s1","s2"],domains:["meaning","mobility"],lever:1,cn:"抵抗理论",en:"Resistance Theory",scholar:"Henry Giroux",work:"Theory and Resistance in Education",year:"1983",disc:"soc",school:"教育批判线",core:"为Willis补上能动性维度：抵抗含批判潜能，不全被再生产回收。",detail:"Giroux 读完 Willis 之后的问题是：如果抵抗都被再生产回收，批判教育学还剩下什么？他把「抵抗」重新概念化：不是所有反抗都算抵抗——要算抵抗，必须包含对支配的批判性意识与解放性潜能，而不只是违规。这给批判教育学补上两个维度：能动性的空间（学生不是被编程的）与教育作为政治实践的场域（学校同时是斗争地点，不只是再生产机器）。1983 年的这本书把弗莱雷的解放教育学接上英美社会学，开创了 critical pedagogy 的学术正典。图谱中它以谱系边接自「学做工/反学校文化」——把 Willis 的民族志发现升格为规范理论：lads 的抵抗是半成品，需要被理论化与引导。边界：批评者认为「抵抗必须有解放潜能」是循环定义，把经验问题变成定义问题；且对「如何从批判意识走向结构变迁」的制度路径说得少——批判教育学后来被学院化，恰恰部分兑现了它自己警告的收编。",links:[{t:"Bloomsbury/Praeger《Theory and Resistance in Education》",u:"https://www.bloomsbury.com/us/theory-and-resistance-in-education-9780897890311/"}]},
{id:"anyon",aka:"阿尼翁 隐性课程",stages:["s1"],domains:["work","mobility"],lever:0,cn:"隐性课程",en:"Hidden Curriculum",scholar:"Jean Anyon",work:"Social Class and the Hidden Curriculum",year:"1980",disc:"soc",school:"教育批判线",core:"工人学校教服从程序、中产学校教执行、精英学校教创造——同一学校的不同课程。",detail:"Anyon 在 1980 年对五所不同阶级社区的小学做了一整年民族志观察，发现同样的五年级课程在四个阶层的学校里根本是不同东西：工人学校教机械程序与服从（抄写、背诵、不求理解），中产学校教「把答案弄对」的执行逻辑，富裕专业学校教创意表达与选择，精英学校教谈判、批判与规则本身的可塑性。她把这叫「隐性课程」——学校教给不同阶级孩子的，其实是他们未来在生产关系中的位置。这篇论文是分层课程最经典的实证范例，虽然样本小但描述力极强。图谱中它以耦合边连「阶级与从众」——Anyon 的分层课程正是 Kohn 那条「职业条件→价值观→教养」链条的学校端生产机器：家庭与学校对同一阶级供给同构的位置预演。边界：描述性民族志，因果机制靠理论推定；学校间差异也混杂资源差，不易拆分隐性课程与物质条件的独立效应；分类带著 1980 年新左派的图式化倾向。",links:[{t:"Journal of Education 原文 (SAGE)",u:"https://journals.sagepub.com/doi/10.1177/002205748016200106"}]},
{id:"oakes",aka:"奥克斯 分轨制 教育分流",stages:["s2"],domains:["mobility","meaning"],lever:0,cn:"分轨制",en:"Tracking",scholar:"Jeannie Oakes",work:"Keeping Track",year:"1985",disc:"soc",school:"教育批判线",core:"校内分轨把社会分层转写为'能力'分层，轨间流动几乎封闭。",detail:"Oakes 的《Keeping Track》处理的是学校内部的分层机器：分轨制把学生按「能力」分进不同轨道，结果是校内复制了校外阶级——高轨学生面对挑战性内容与高期望教师，低轨学生面对稀释内容、低期望与污名同侪，且轨间流动几乎封闭，一次早期分班决定后续全部。她用数据证明分轨不只反映差异，更生产差异：进入低轨本身就是成绩下滑的独立预测因子。这本书推动了后来的 detracking 改革运动，也是「制度把社会不平等转写为能力不平等」的标本。图谱中它以耦合边连「有效维持不平等」——分轨恰恰是 EMI 的校内执行器：当入学数量普及，优势阶级退守质量维，校内分轨把阶级差重新编码为能力差。边界：分轨与因材施教的界线在政策中极难划；Oakes 的规范结论（废除分轨）强于其因果证据，后续研究对混编是否提升低轨生成绩的结果不稳定。",links:[{t:"Yale UP《Keeping Track》",u:"https://yalebooks.yale.edu/book/9780300108309/keeping-track/"}]},
{id:"macleod",aka:"麦克劳德 志向调平 志向持平",stages:["s2"],classes:["c1"],domains:["mobility","meaning"],lever:0,cn:"志向持平",en:"Leveled Aspirations",scholar:"Jay MacLeod",work:"Ain't No Makin' It",year:"1987/2009",disc:"soc",school:"教育批判线",core:"美国版Willis：成就意识形态幻灭→志向主动下调；黑人Brothers组显示种族维度。",detail:"MacLeod 把 Willis 的问题搬到美国公屋：Clarendon Heights 的两组青少年——白人 Hallway Hangers 幻灭、吸毒、预期没有未来；黑人 Brothers 却虔诚相信成就意识形态，努力读书守规矩。二十年后追踪：Brothers 的信仰也没兑现——两组最后都留在原阶级，只是一组「主动撤退」、一组「努力后被退货」。他的概念「志向持平」：期望不是天真乐观也不是宿命，而是被「现实可能集」逐步调平。Brothers 组是反例的富矿：种族化的位置反而维持对制度的信任。图谱中它以谱系边接自「学做工/反学校文化」（美国版移植+种族维度），耦合边连「受挫的成年」（志向持平→治疗性成年的代际续篇），张力边同时连「赞助/竞争流动」（竞争承诺的阶级配给幻觉）与「文化生态/对抗认同」（Brothers 信成就意识形态是对 Ogbu 预测的直接反例）。边界：与 Willis 同是小样本民族志+长期追踪；Brothers 的反例显示成就意识形态的穿透力比欧洲版预估的强，单一社区推广有限。",links:[{t:"Routledge《Ain't No Makin' It》三版",u:"https://www.routledge.com/Aint-No-Makin-It-Aspirations-and-Attainment-in-a-Low-Income-Neighborhood-Third-Edition/MacLeod/p/book/9780813343587"}]},
{id:"ogbu",aka:"奥格布 对抗认同 非自愿少数",stages:["s1","s2"],domains:["mobility","meaning"],lever:0,cn:"文化生态/对抗认同",en:"Oppositional Identity",scholar:"John Ogbu",work:"Minority Education and Caste",year:"1978",disc:"soc",school:"教育批判线",core:"非自愿少数群体把学校成功编码为'背叛族群'→主动低投入；种族×阶级交叉节点。",detail:"Ogbu 的文化生态模型要解释：为什么某些少数族裔的学校成就差距在控制阶级后依然顽固？答案在于「非自愿少数群体」——被征服、奴役或殖民而纳入的群体（对比移民这种自愿少数），他们把教育系统体验为压迫者的制度，学校成功被编码成「背叛族群、行为白化」——于是出现对抗认同：主动低投入作为集体尊严的保护。这个模型把族裔成就差从缺陷论（文化或基因问题）转为历史结构解释，并用跨国比较（日本部落民、印度贱民、英国西印度裔）支撑其普遍性。图谱中它以张力边接「志向持平」——MacLeod 的 Brothers（黑人组）虔诚相信成就意识形态，正是对「非自愿少数必生对抗」预测的直接反例，这条反例边让两个民族志互相校准。边界：对抗认同被批评过度同质化非裔经验、忽略阶级与性别内部分化；自愿/非自愿二分在混杂迁移史上太干净；Fordham 等后续证明「行为白化」指控的真实性远比叙述复杂。",links:[{t:"ERIC《Minority Education and Caste》记录",u:"https://eric.ed.gov/?id=ED156791"}]},
{id:"rivera",aka:"里维拉 精英招聘 文化匹配",stages:["s2","s3"],classes:["c3"],domains:["work","mobility"],lever:0,cn:"血统/精英招聘",en:"Pedigree",scholar:"Lauren Rivera",work:"Pedigree",year:"2015",disc:"soc",school:"教育批判线",core:"顶级雇主以'文化匹配/谈吐打磨'筛选，把阶级信号伪装成才能评估。",detail:"Rivera 潜入顶级投行、咨询与律所的招聘链，发现「择优」全流程是阶级信号的洗白系统：简历筛选迷信名校（不只是品质信号而是同类人保证），面试考「文化匹配」与 polish（谈吐、闲聊话题、肢体从容），这些被当成才能评估的东西其实是上层经验的产品——玩什么运动、去过什么地方，全是可以花钱买的。她还点出自我复制偏误：面试官选「像当年的我」的人。这本 2015 年的书拿下 ASA 多项奖，把招聘端从才能市场重写为阶级再生产的下游终点。图谱中它的边全是耦合：接「有效维持不平等」（数量饱和后竞争转质量维的雇用端版本）、「特权/从容」（Khan 训练的从容正是招聘端被识别的内容）、「赞助/竞争流动」（文化匹配=赞助制通道）、「制造阶级」（文理学院招生是同款机制的上游）、「惯习·场域·资本」（文化资本被洗白成 fit）。边界：样本限于最顶端 EPS 职位，对中层劳动市场外推有限；匹配也有真实协调功能，理论难划清过滤阶级与过滤能力的实证边界。",links:[{t:"Princeton UP《Pedigree》",u:"https://press.princeton.edu/books/hardcover/9780691155623/pedigree"}]},
{id:"jack_poor",aka:"杰克 特权穷人 双重弱势",stages:["s2","s3"],classes:["c1"],domains:["mobility","money","relation"],lever:0,cn:"特权穷人",en:"The Privileged Poor",scholar:"Anthony Jack",work:"The Privileged Poor",year:"2019",disc:"soc",school:"教育批判线",core:"精英大学贫困生内部分化：预科洗礼过的'特权穷人'vs'双重弱势'——同格子内经验迥异。",detail:"Jack 揭示「贫困生」在精英大学内部根本是两个群体：「特权穷人」——经由奖学金项目被送进 Exeter、Andover 等预科洗礼过的孩子，他们带著二手的精英惯习入场；「双重弱势」——直接从社区公立高中来的，他们在同一间宿舍里撞上完全不同的世界。这个区分解释了为什么同样「第一代」标签下体验天差地别：预科经验供给了对教授办公时间、社交隐规则、甚至洗衣卡系统的操作手册。书里最尖锐的细节是「奖学金学生做清洁工」的羞辱性设计——制度自己暴露了接纳的限度。图谱中它以耦合边连「制造阶级」——Stevens 解剖招生官怎么制造阶级，Jack 解剖被制造出来的学生怎么活，同一格位内部的分化证据互为上下游。边界：田野在单一精英大学，双群体二分在其他制度环境（大型公立校）中适用性待考；「特权穷人」概念易让人误读为责怪预科生——Jack 的重点恰恰是制度筛选了哪种贫困者被允许进入。",links:[{t:"Harvard UP《The Privileged Poor》",u:"https://www.hup.harvard.edu/books/9780674248243"}]},
{id:"stevens",aka:"史蒂文斯 制造阶级",stages:["s2"],classes:["c3"],domains:["mobility"],lever:0,cn:"制造阶级",en:"Creating a Class",scholar:"Mitchell Stevens",work:"Creating a Class",year:"2007",disc:"soc",school:"教育批判线",core:"精英文理学院招生流程如何把家庭资源转译为'个人优秀'。",detail:"Stevens 花了 18 个月在新英格兰一所精英文理学院的招生办里当参与观察者，写下「阶级是如何被制造出来的」微观民族志：招生官看似评选个人，实际执行的是一整套转译机器——leadership、character、fit 这些评估词把家庭资源（昂贵高中、课外活动经费、父母能动员的关系）洗白成个人素质。他还拆解了招生办自身的组织逻辑：运动员配额、捐赠者子女、地域多样性这些机构需求在暗处占据录取名额，「全面评估」的话术让每个决定看起来都像才德裁量。图谱中它以耦合边接「特权穷人」（同一格位内：招生端制造阶级、入学后内部分化）与「血统/精英招聘」（文理学院招生=顶级雇主文化匹配的上游同款机制：都是把继承伪装成选拔）。边界：单一机构民族志，且该校的文理学院生态与研究型大学、大型公立有别；规范性判断（哪些偏好算不公）留有争议空间。",links:[{t:"Harvard UP《Creating a Class》",u:"https://www.hup.harvard.edu/books/9780674034945"}]},
// ── 教养民族志/家庭机制 ──
{id:"kohn",aka:"科恩 阶级与从众",stages:["s1","s3","s4"],domains:["work","family"],lever:0,cn:"阶级与从众",en:"Class and Conformity",scholar:"Melvin Kohn",work:"Class and Conformity / Work and Personality",year:"1969/1983",disc:"soc",school:"教养机制",core:"职业的自我导向机会→父母价值观(自主vs服从)→教养取向——阶层写入童年的中层因果链。",detail:"Kohn 花了三十年做一条中层因果链：职业条件→价值观→教养。核心发现：工作提供「自我导向」机会的程度（复杂度、受监督程度、例行化程度）决定父母看重什么——专业阶级工作奖励自主判断，父母就重视孩子的内在标准；劳工工作奖励服从，父母就重视孩子听话守规。后来的跨国与纵贯研究（Kohn & Schooler）证明方向是双向的：职业塑造价值观，价值观也选人进职业。这是把阶级写进童年的第一个严格量化模型，也是「教养差异有结构原因」的奠基证据。图谱中它的耦合网最实用：接「协作培养/自然成长」（Kohn 的价值观链条是 Lareau 民族志的量化前身，价值→实践互证）、「自主支持教养」（自我导向价值落地为自主支持 vs 心理控制的具体实践）、「权威人格」（Adorno 的权威养育×Kohn 的阶级条件=汇聚证据）、「教养类型学」（Baumrind 权威型最优是有阶级条件的）、「隐性课程」（Anyon 的分层课程是同一逻辑的学校端）。边界：关联性设计为主，中介机制（工作压力、时间）后来才被补上；阶级内部变异大，且「从众」在新经济下可能正被「弹性适应」重写。",links:[{t:"U Chicago Press《Class and Conformity》",u:"https://press.uchicago.edu/ucp/books/book/chicago/C/bo5965950.html"}]},
{id:"lareau",aka:"拉鲁 不平等的童年 协作培养",stages:["s1","s3","s4"],domains:["family","mobility"],lever:0,cn:"协作培养/自然成长",en:"Concerted Cultivation",scholar:"Annette Lareau",work:"Unequal Childhoods",year:"2003",disc:"soc",school:"教养机制",core:"中产协商说理+日程编排产'权利感'，贫劳指令式+自由玩耍产'约束感'——差异模式而非缺陷。",detail:"Lareau 跟踪 12 个家庭数年，提出两种教养逻辑：中产的「协作培养」——密集排程活动、跟孩子说理协商、示范如何对制度提要求，产出的是「权利感」（孩子敢于对老师医生提需求）；劳工与贫困家庭的「自然成长」——保障温饱后让孩子自由发展、指令式沟通、对机构保持距离，产出的是「约束感」与对制度的疏离。她再三强调两种模式各有优缺（自然成长的孩子更放松、手足关系更密），问题不在哪种「好」，而在于学校与机构只奖励其中一种——差异被制度兑现成不平等。图谱中它是耦合枢纽：接「惯习·场域·资本」（协作培养=惯习养成的民族志兑现）、「阶级与从众」（Kohn 链的田野版）、「言说的方式」「观察投入式学习LOPI」（跨文化对照）、「生态系统/PPCT」（家-校中系统错配）、「语言编码」（编码×培养的经典配对）、「技能形成技术」（协作培养=动态互补的具体投入）、「社会资本(创造人力资本)」（封闭网络是协作培养的结构条件）；唯一张力边来自「过渡空间/真假我」——日程编排可能压缩闲散与游戏的发展功能。边界：阶级×模式对应是倾向非铁律；权利感的收益依赖制度类型；样本小，推广靠理论饱和而非统计代表。",links:[{t:"UC Press《Unequal Childhoods》",u:"https://www.ucpress.edu/books/unequal-childhoods/paper"}]},
{id:"collins",aka:"柯林斯 文凭社会 文凭通胀",stages:["s2","s3"],domains:["mobility","work"],lever:0,cn:"文凭社会",en:"The Credential Society",scholar:"Randall Collins",work:"The Credential Society",year:"1979",disc:"soc",school:"教育批判线",core:"文凭通胀是供给侧驱动的地位群体竞争——职位技术要求未驱动扩张，技能多在职习得。",detail:"Collins 1979 年的《文凭社会》翻了教育扩张的标准叙事：主流说法（技术功能论）认为经济升级要求更多技能、教育供给于是跟进；他证明职位所需的实际技能几乎没有同步上升，多数技能是在职学的，真正膨胀的是「入场券要求」——教育是地位群体竞争的武器：每个群体用文凭设置封闭边界，于是文凭通膨变成自我驱动的螺旋，跟生产率脱钩。这是供给侧驱动的不平等理论：不是技能不够所以设门槛，而是为了设门槛所以制造技能话语。图谱中它以耦合边连「有效维持不平等」——文凭通膨正是 EMI 质量维维持的动力机制；张力边双线作战——对「人力资本」（教育造技能 vs 教育筛人的核心对立）与「教育与技术的赛跑」（Goldin & Katz 的需求驱动解释 vs Collins 的供给驱动）。边界：「技能多数在职习得」对医学工程等强技术领域不成立；文凭也确实有筛选功能，两个机制可以共存，Collins 的版本把信号贬得太干净。",links:[{t:"Columbia UP《The Credential Society》",u:"https://cup.columbia.edu/book/the-credential-society/9780231549783/"}]},
// ── 阶级经验/尊严 ──
{id:"sennettcobb",aka:"森尼特 科布 隐性伤害",stages:["s3","s4"],classes:["c1"],domains:["meaning","work","mobility"],lever:0,cn:"阶级隐痛",en:"Hidden Injuries of Class",scholar:"Sennett & Cobb",work:"The Hidden Injuries of Class",year:"1972",disc:"soc",school:"阶级经验",core:"向上流动叙事使工人把结构位置体验为个人失败；尊严靠'为子女牺牲'赎回。",detail:"Sennett & Cobb 访谈波士顿蓝领工人，问的不是钱而是伤：为什么物质改善后阶级痛感没消失？他们的答案是「隐性伤害」——向上流动叙事让每个位置看起来像个人审判，工人把结构性位置体验为「我不够格」的自我指责；同时这套叙事供给了救赎机制：为孩子牺牲（我没出息但要让孩子有）把失败转写成尊严投资。他们称之为「能力的徽章」问题——社会只承认文凭化这一种能力，其他能力不算数，于是缺徽章者要么自我贬抑、要么发展出替代性的尊严语法。图谱中它的谱系两条都重要：放出「坠落恐惧」（同一诊断镜头转向专业管理阶级）与「阶级的道德意义」（Sayer 把尊严/羞耻的道德语法形式化）；上游谱系来自「拟剧论/污名」（受损身份的互动力学是隐痛的微观基础）；耦合接「流动现代性/有缺陷的消费者」（Bauman 的消费资格丧失是隐痛的当代形态）、「受挫的成年」（治疗性成年=隐痛的新形态）、「道德-文化边界」（工人的尊严话语）。边界：诠释性访谈，缺乏量化验证；1972 年的美国蓝领经验已被 Silva 与 Standing 在去工业化语境下分别续写。",links:[{t:"Norton《The Hidden Injuries of Class》",u:"https://wwnorton.com/books/9780393310856"}]},
{id:"ehrenreich",aka:"埃伦赖希 坠落恐惧 职业管理阶级",stages:["s3","s4"],classes:["c2"],domains:["work","meaning"],lever:0,cn:"坠落恐惧",en:"Fear of Falling",scholar:"Barbara Ehrenreich",work:"Fear of Falling",year:"1989",disc:"soc",school:"阶级经验",core:"专业管理阶级(PMC)以自我定义于'与劳工不等同'，核心焦虑是向下流动。",detail:"Ehrenreich 把镜头从底层转向「专业管理阶级」（PMC）——医生、律师、教授、经理这群靠知识与文化资本占位的人。她的诊断：PMC 的阶级认同建立在否定式上——「我们不是他们（劳工）」，而这个位置结构性不稳：无法世袭（每代都要重新考试）、依附制度（文凭是唯一资产）、且向下流动永远是个人失败而非结构意外。于是「坠落恐惧」成为这个阶级的集体心理底色：既驱动自我剥削式的努力，也驱动对下层的防御性鄙视与道德恐慌——从六十年代的发现贫困到八十年代的 underclass 话语，PMC 在同情与恐惧间摆荡。图谱中它以谱系边接自「阶级隐痛」——Sennett & Cobb 对蓝领尊严的解剖方法被转用到中产顶层，同一个「位置体验为个人审判」的框架。边界：PMC 概念继承自 Ehrenreich 夫妇更早的论战文章，其阶级定位（新阶级还是雇佣劳动者）在马克思传统内有争议；文体介于评论与研究之间，实证深度不如其影响力。",links:[{t:"Google Books《Fear of Falling》(Pantheon 1989)",u:"https://books.google.com/books/about/Fear_of_Falling.html?id=CW_aAAAAMAAJ"}]},
{id:"sayer",aka:"塞耶 阶级的道德意义",domains:["meaning","money"],lever:0,cn:"阶级的道德意义",en:"Moral Significance of Class",scholar:"Andrew Sayer",work:"The Moral Significance of Class",year:"2005",disc:"soc",school:"阶级经验",core:"阶级经验本质是规范性的——善恶、应得、羞耻的道德语法，不止资源分配。",detail:"Sayer 主张阶级经验本质上是规范性的：人不只占有不等量的资源，还活在「我值得什么、别人怎么看我」的道德语法中——阶级的位置同时是评价的位置，所以它有道德重量。他用道德哲学（承认、应得、羞耻）重新解剖阶级经验：羞耻不是阶级的副作用而是其日常形态；「应得感」是统治的心理装置（优势者把运气读成美德）；「尊重」是不平等的真正货币之一。这本书等于给 Sennett & Cobb 的民族志发现配上哲学底盘，也把布迪厄的符号暴力补上伦理学语言——被支配者承认那把尺，正是因为那把尺以道德词汇呈现。图谱中它以谱系边接自「阶级隐痛」——把访谈里的尊严话语与羞耻经验系统化为「阶级的规范维度」理论。边界：批评者认为 Sayer 的规范立场（阶级在道德上是坏的）与分析混在一起，实证研究者嫌它不够可操作化；但支持者说这正是重点——阶级研究假装价值中立才是真的不严谨。",links:[{t:"Cambridge Core《The Moral Significance of Class》DOI",u:"https://doi.org/10.1017/CBO9780511488863"}]},
{id:"lubrano",aka:"卢布拉诺 跨阶层者",stages:["s3","s4"],classes:["c1","c2"],domains:["mobility","meaning"],lever:0,cn:"跨阶层者",en:"Straddler / Limbo",scholar:"Alfred Lubrano",work:"Limbo: Blue-Collar Roots, White-Collar Dreams",year:"2003",disc:"soc",school:"阶级经验",core:"蓝领出身白领谋生者悬于两界，向上流动伴随忠诚冲突与双重文化失能。",detail:"Lubrano 的《Limbo》写的是阶级穿越者的内战：蓝领出身、白领谋生的 straddlers 悬在两个世界之间——在办公室里永远觉得自己是卧底（不懂隐形规则、没有随口的自信），回老家又被当成变节者。他把代价列得很具体：忠诚冲突（对家人的愧疚）、双重文化失能（哪边都不是完整成员）、以及向上流动附带的「情感分手费」——与原生阶级的价值观决裂被经验为背叛。这本书一半是记者的采访故事一半是社会学概念，把向上流动的代价从抽象变成可辨认的经验目录。图谱中它以耦合边连「主体-客体五阶」（Kegan 的「发展=失去社会环绕」体感，穿越者的失重正是发展性变动的成本版）与「阶级穿越者」（Jaquet 的 complexion 概念把 straddler 经验形式化：穿越者不是被单一惯习决定，而是被多重位置构成）。边界：自述加访谈混编，无系统抽样；聚焦美国蓝领→白领单向穿越，对向下与横向穿越不适用；治疗性语气浓，分析框架相对浅。",links:[{t:"Google Books《Limbo》(Wiley 2004)",u:"https://books.google.com/books/about/Limbo.html?id=q1yI-TiSOAAC"}]},
{id:"young_merit",aka:"迈克尔·杨 优绩制 精英统治",domains:["mobility","work"],lever:0,cn:"优绩制的崛起",en:"The Rise of the Meritocracy",scholar:"Michael Young",work:"The Rise of the Meritocracy",year:"1958",disc:"soc",school:"阶级经验",core:"'meritocracy'本是反乌托邦讽刺：能力贵族取代世袭贵族同样残暴——Sandel的概念史源头。",detail:"这是概念史的重头戏：meritocracy 这个词 1958 年由社会学家 Michael Young 发明，而且本来是反乌托邦讽刺——他虚构了一个 2033 年的英国，智商测验加努力彻底决定阶级，结果「能力贵族」比世袭贵族更残暴，因为优势者真心相信自己配得上，劣势者连抱怨的道德资源都被剥夺——「你穷因为你笨」是这个系统的官方立场。讽刺的是，这个词很快被脱去反讽外衣，变成英美政治的自我标榜，Blair 和后来整整两代政客都把它当褒义词用，Young 晚年还特别撰文抗议这种误读。图谱中它以谱系边连「绩优暴政」——Sandel 六十年后重启 Young 的诊断：胜者傲慢、输者羞辱，文凭主义成为最后可接受的偏见，等于把反乌托邦读成了时事评论。边界：Young 的假设是能力可测量且固定，这个前提本身已被发展科学松动；批评者指出他低估了经济结构对能力需求的决定作用——能力不是自变量。",links:[{t:"Routledge《The Rise of the Meritocracy》",u:"https://www.routledge.com/The-Rise-of-the-Meritocracy/Young/p/book/9781560007043"}]},
{id:"sandel",aka:"桑德尔 精英的傲慢 绩优暴政",domains:["work","meaning","mobility"],lever:0,cn:"绩优暴政",en:"Tyranny of Merit",scholar:"Michael Sandel",work:"The Tyranny of Merit",year:"2020",disc:"soc",school:"阶级经验",core:"择优叙事让赢家傲慢(运气=应得)、输家羞辱；文凭主义成为'最后可接受的偏见'。",detail:"Sandel 把 Young 的反乌托邦读成诊断书：优绩叙事有双重毒性——让赢家把运气（出身、时代、天赋的彩票）读成「应得」于是傲慢；让输家接受「我活该」的羞辱，因为这个系统承诺过公平。他的火力点是文凭主义：大学学位从入场券变成道德判决书，「没读大学」在美国话语里几乎等同人格缺陷——他称之为最后可接受的偏见。解方是重建工作的尊严：把评价重心从消费与认证能力转向生产贡献。这本 2020 年的书精准命中民粹愤怒的解剖点，也成为自由派反思精英政治的标准文本。图谱中它以谱系边接自「优绩制的崛起」——概念史的直接兑现：Young 的讽刺预言被当代民粹反弹证实。边界：Sandel 的规范方案（贡献正义、工资与尊严挂钩）被批评模糊——贡献由谁定义？他也相对低估种族与性别在不满情绪中的独立权重，把他的诊断当作全部解释会失真。",links:[{t:"Macmillan Academic《The Tyranny of Merit》",u:"https://academic.macmillan.com/academictrade/9781250800060/thetyrannyofmerit/"}]},
{id:"standing",aka:"斯坦丁 朝不保夕者 不稳定无产阶级",stages:["s3","s4"],classes:["c1"],domains:["work","money","health"],lever:0,cn:"不稳定无产者",en:"The Precariat",scholar:"Guy Standing",work:"The Precariat",year:"2011",disc:"soc",school:"阶级经验",core:"缺七种劳动安全的新阶级形态，情绪产出4A：anger/anomie/anxiety/alienation。",detail:"Standing 命名了一个新阶级形态：precariat——缺乏七种劳动安全保障（劳动市场、雇用、工作、技能再生产、收入、代表权、以及由工作建立的叙事身份）的人群，他们活在临时合约、零工与随时待命里，时间结构被切碎导致无法规划人生。这个阶级的心理产出是 4A：anger（对处境的愤怒）、anomie（无规范可依）、anxiety（不确定性焦虑）、alienation（劳动与自我脱钩）。他警告这个阶级内部分裂（前劳工、移民、失意毕业生互不认同），是民粹动员的火药库——危险的正是它还没成为「自为阶级」。图谱中它的耦合网：接「流动现代性/有缺陷的消费者」（precariat=Bauman 诊断的阶级形态）、「好工作坏工作」（Kalleberg 的非标准就业是它的劳动市场面）、「绝望死亡」（Case & Deaton 的研究人群高度重叠）、「负债人」（Lazzarato 的债务-内疚装置为不稳定化供能）。边界：「新阶级」宣称被批评——批评者说这是劳动市场状态而非阶级位置（成员阶级出身各异）；七种安全清单带著北欧模式基准，对全球南方的适用性需调整。",links:[{t:"Bloomsbury《The Precariat》(开放获取)",u:"https://www.bloomsbury.com/ca/precariat-9781849664561/"}]},
{id:"bergerluckmann",aka:"伯格 卢克曼 现实的社会建构",domains:["meaning","relation"],lever:0,cn:"实在的社会建构",en:"Social Construction of Reality",scholar:"Berger & Luckmann",work:"The Social Construction of Reality",year:"1966",disc:"soc",school:"阶级经验",core:"nomos(意义秩序)遮蔽失范威胁；意义由社会分配而非个人生产——模型的社会学锚点。",detail:"Berger & Luckmann 1966 年的《实在的社会建构》是知识社会学的奠基文本：我们当成「自然实在」的东西是辩证过程的产品——外在化（人把意义倒进世界）→客体化（意义凝固成制度与事实）→内在化（制度回头塑造经验者）。核心概念 nomos 是社会提供的意义秩序：它把混乱的世界包进一个「事情就是这样」的帐篷，遮蔽失范与无意义的威胁；而「可信性结构」是维持帐篷的人际网络——你身边的人相信什么，世界就是什么。意义不由个人生产而由社会分配，这句话是整张图谱中意义与叙事线的社会学锚点。图谱中它以耦合边连「诠释学人类学」——Geertz 的「意义之网」与 Berger 的「可信性结构」是同一命题的人类学与社会学版本：人都悬在自己编的网里，只是网有阶级配给。边界：「建构」常被误读为「实在不存在」（两位作者其实反对这种虚无阅读）；辩证循环难以操作化，后续多用其概念而非检验其模型。",links:[{t:"Penguin Random House《The Social Construction of Reality》",u:"https://www.penguinrandomhouse.com/books/12390/the-social-construction-of-reality-by-peter-l-berger/"}]},
// ── 精英研究 ──
{id:"veblen",aka:"凡勃伦 有闲阶级论 炫耀性消费",classes:["c3"],domains:["money","relation"],lever:0,cn:"有闲阶级论",en:"Conspicuous Leisure",scholar:"Thorstein Veblen",work:"The Theory of the Leisure Class",year:"1899",disc:"soc",school:"精英研究",core:"炫耀性消费与炫耀性休闲作为地位的浪费性证明——精英符号理论的原点。",detail:"Veblen 1899 年的《有闲阶级论》是精英符号理论的原点：地位必须被浪费性地展示才有效——炫耀性休闲（有闲到可以学无用之事：古典语言、礼仪、狩猎）与炫耀性消费（买超出功能的东西）都是金钱竞赛中的声望凭证。他还指出一个反向机制：下层模仿上层的消费标准，于是浪费性品味向下渗透成全民规范。书里对「高等教育作为金钱文化延伸」的讽刺至今仍是精英文凭研究的暗线。这本书方法很怪——进化论加人类学加讽刺文体——但概念穿透力极强。图谱中它以谱系边连「权力精英」——Mills 把 Veblen 对有闲阶级的文化批判改写为机构顶端的权力分析：从炫耀什么转向谁在决策。边界：Veblen 的演化语言（未开化特质的遗存）带著 19 世纪包袱；炫耀性消费在当代的形态已被 Khan 改写——精英不再炫耀，而是展示从容与无所不包，Veblen 解释浪费好过解释隐形的当代区隔。",links:[{t:"Project Gutenberg 全文",u:"https://www.gutenberg.org/ebooks/833"}]},
{id:"mills",aka:"米尔斯 权力精英",classes:["c3"],domains:["money","work"],lever:0,cn:"权力精英",en:"The Power Elite",scholar:"C. Wright Mills",work:"The Power Elite",year:"1956",disc:"soc",school:"精英研究",core:"军-政-经三大机构高层互换循环构成统一权力精英，中层无力化。",detail:"Mills 1956 年的《权力精英》是对美国权力结构的正面挑战：决策不是民主的产物，而是军、政、经三大机构顶层一小撮人的产物——他们出身相同学校、进相同俱乐部、在董事会与政府职位之间互换循环，构成统一的权力精英。关键机制是「互换性」：将军当董事、CEO 进国防部、政客退休做说客，于是三大机构的利益自然对齐；而中层（工会、地方社会、国会）只剩执行权，底层是大众社会——被动员而非参与的原子化人群。图谱中它以谱系边接自「有闲阶级论」（Veblen 的文化符号批判→Mills 的机构权力分析），又以谱系边放出「阶级支配网络」——Domhoff 把 Mills 的判断变成可验证的网络命题：董事互锁、基金会与政策网络把阶级转成统治。边界：多元主义者（Dahl 等）批评 Mills 把潜在权力当成实际支配，缺乏决策过程的个案证据；三大机构的统一性在政党极化与科技资本崛起后需要重写——但互换机制本身仍被反复证实。",links:[{t:"Oxford UP《The Power Elite》",u:"https://www.oupcanada.com/catalog/9780195133547.html"}]},
{id:"domhoff",aka:"多姆霍夫 谁统治美国",classes:["c3"],domains:["money","relation"],lever:0,cn:"阶级支配网络",en:"Class-Domination Theory",scholar:"G. William Domhoff",work:"Who Rules America?",year:"1967",disc:"soc",school:"精英研究",core:"董事互锁+基金会+政策网络把上层阶级转为统治阶级——权力精英的网络实证化。",detail:"Domhoff 是 Mills 路线的实证化工程师：《谁统治美国？》1967 年起连出八版，用网络方法把「上层阶级」与「统治阶级」的关系拆成可验证的部件——董事互锁（同一批人坐在多家公司董事会）、政策规划网络（基金会加智库加政策讨论团体把商业共识变成政策备选案）、候选人支持与游说管道。他的四网络模型证明上层阶级不是纯社会类别而是有组织的统治机器：经济资本→机构网络→政策输出。配套的 whorulesamerica.net 网站持续更新数据，是精英研究少见的开放资料库。图谱中它以谱系边接自「权力精英」（Mills 的互换直觉被操作化为互锁测量），以耦合边连「富人为何捐赠」——Ostrower 证明慈善恰是这个网络的再生产环节：捐赠换回董事会席位与阶级边界。边界：网络密度高不等于指令传导有效，批评者说互锁可能主要是资讯管道而非命令链；方法上对反事实（如果网络不存在政策会如何）处理较弱。",links:[{t:"WhoRulesAmerica.net 官方网站",u:"https://whorulesamerica.ucsc.edu/"},{t:"第八版介绍页",u:"https://whorulesamerica.ucsc.edu/wra8.html"}]},
{id:"khan",aka:"可汗 特权 圣保罗中学",stages:["s2"],classes:["c3"],domains:["relation","mobility"],lever:0,cn:"特权/从容",en:"Privilege as Ease",scholar:"Shamus Khan",work:"Privilege: St. Paul's School",year:"2011",disc:"soc",school:"精英研究",core:"新精英培养'从容'(ease)而非排他品味：在高低文化间自如穿梭的身体技术。",detail:"Khan 回母校圣保罗学校教书一年做民族志，发现新精英的秘密不再是老派的排他品味（听歌剧、懂红酒），而是「从容」：在高低文化间自如穿梭的身体技术——能跟校工聊家常也能谈布赫迪厄，能听碧昂丝也能听巴哈，把等级制度体验为梯子而非墙。这种 omnivore 态度比炫耀性品味更难模仿，因为它必须看起来毫不费力——从容是把继承的优势呈现为个人天赋的完美伪装。学校真正教的不是知识，是这种在一切场合自在的惯习。图谱中它以谱系边接自「惯习·场域·资本」——Khan 用从容重写精英惯习：omnivore 取代排他品味成为新区隔；耦合边接「血统/精英招聘」——学校训练的从容正是 Rivera 在招聘端看到被当成文化匹配评估的东西。边界：单一寄宿学校的民族志，且 Khan 的内部人身份带来可亲性偏误；从容概念的测量困难与其理论重量不成比例；批评者问：这是真区隔还是区隔的表演？",links:[{t:"Princeton UP《Privilege》",u:"https://press.princeton.edu/books/paperback/9780691156231/privilege"}]},
{id:"ostrower",aka:"奥斯特罗尔 富人为何捐赠",stages:["s3","s4"],classes:["c3"],domains:["money","relation"],lever:0,cn:"富人为何捐赠",en:"Why the Wealthy Give",scholar:"Francie Ostrower",work:"Why the Wealthy Give",year:"1995",disc:"soc",school:"精英研究",core:"慈善=地位再生产循环：捐赠买回董事会席位、身份与阶层边界。",detail:"Ostrower 访谈近百位纽约富豪捐赠者，发现精英慈善不是「给出去」而是「绕一圈回来」：捐款买到董事会席位（大都会、歌剧院、大学），席位买到身份与社会位置，而进入哪个委员会、出席哪个晚宴又再划出阶级内部的尊卑线——慈善是地位再生产的闭环，利他话语是这台机器的润滑油而非引擎。她还发现捐赠方向高度遵循阶级内部规范（同侪给什么就给什么），且公益与自利的区分在这个世界里根本无效——两者是同一动作的两面。图谱中它以耦合边接「阶级支配网络」——Domhoff 的政策网络正是由这些基金会与董事会构成，捐赠是网络的再生产端；又接两条存在主义线：「不朽工程/vital lie」（Becker 的死亡否认以基金会、冠名、信托为物质形式）与「象征不朽五模式」（Lifton 的创造模式的精英兑现）。边界：样本限于纽约顶层旧钱慈善圈，对新钱（矽谷式有效利他）与企业慈善的解释力递减；受访者的自我呈现偏误只能靠访谈技巧部分控制。",links:[{t:"Princeton UP《Why the Wealthy Give》",u:"https://press.princeton.edu/books/paperback/9780691015880/why-the-wealthy-give"}]},
// ── 生命历程 ──
{id:"elder",aka:"埃尔德 生命历程 大萧条的孩子",domains:["family","mobility","money"],lever:1,cn:"生命历程五原则",en:"Life Course Theory",scholar:"Glen Elder",work:"Children of the Great Depression",year:"1974/1999",disc:"soc",school:"生命历程",core:"历史时空/时机/关联生命/能动性四原则；同一冲击的效应取决于受冲击时的发展年龄。",detail:"Elder 用奥克兰 1920-21 年出生的 167 人从童年追踪到中年，把「大萧条怎么改变人」写成了生命历程研究的范式起点。他提炼出后来被奉为经典的原则框架：历史时空（效应取决于生在何时何地）、时机（同一冲击在不同发展年龄打中不同东西——大萧条对幼年是家庭压力、对青少年是提前当家）、关联生命（你被卷进别人的命运，如父亲失业改变全家）、能动性（人在约束中仍建构路径）。最具影响力的反直觉发现：大萧条对当时的青少年反而是磨练（早担责任→成年后更稳），对幼童才是伤害——冲击效应是发展阶段的函数。图谱中它承接「年龄分层」的谱系（Riley 的队列流×年龄分层是范式的结构前身），放出「延迟成人/制度撤退」（范式应用到当代）；以张力边连「惯习·场域·资本」——人建构生命历程 vs 惯习即历史的本体论对峙（Hitlin & Elder 的桥：能动性本身是位置函数）。边界：单一城市单一队列，推广靠复制研究支撑；能动性原则被批评太美国式乐观，结构权重因体制而异。",links:[{t:"Routledge《Children of the Great Depression》25周年版",u:"https://www.routledge.com/Children-Of-The-Great-Depression-25th-Anniversary-Edition/Elder/p/book/9780813333427"}]},
{id:"riley",aka:"赖利 年龄分层 队列流",stages:["s4"],domains:["work","meaning"],lever:0,cn:"年龄分层",en:"Age Stratification",scholar:"Matilda W. Riley",work:"Aging and Society / Age and Structural Lag",year:"1972/1994",disc:"soc",school:"生命历程",core:"队列流(cohort flow)穿越按年龄分层的角色结构；现代化造成'结构滞后'。",detail:"Matilda Riley 的「年龄分层」把年龄从人口学变量升格为社会结构：每个社会把角色按年龄分层（什么岁数该做什么），而一个个出生队列像水流一样穿越这个相对固定的角色结构——队列流与角色结构是两个不同时钟，它们的错位产生历史变迁。她后来提出「结构滞后」：人的寿命与生命历程改变了（退休后还有二十年），但角色结构没跟上（制度仍按旧寿命设计），于是出现规范真空的「无角色角色」——退休者、延迟的青年。这个框架是理解「三十不立」为何不只是个人焦虑而是制度设计问题的钥匙。图谱中它以谱系边连「生命历程五原则」——队列流×年龄分层正是 Elder 范式中历史时空与时机原则的结构前身：先有人把年龄写成结构，才有后来把人生写成轨迹。边界：结构主义倾向强，对「为什么角色结构改不动」的权力分析薄；队列流隐含的每个队列走同一条河的假设，在去制度化时代部分失效。",links:[{t:"Russell Sage《Aging and Society》Vol.3",u:"https://www.russellsage.org/publications/book/aging-and-society-volume-3"}]},
{id:"cad",aka:"默顿 马太效应 累积优势 丹尼弗",domains:["mobility","money","health"],lever:0,cn:"累积(不)优势",en:"Cumulative (Dis)advantage",scholar:"Merton → Dannefer → DiPrete & Eirich",work:"Matthew Effect 1968 / ARS综述",year:"1968/2006",disc:"soc",school:"生命历程",core:"初始位置差经正反馈复利放大：'凡有的还要加给他'——队列内不平等随年龄发散。",detail:"累积（不）优势是不平等的复利模型：Merton 1968 年用「马太效应」命名——「凡有的还要加给他」，他在科学界观察到名声本身就是资源：有名气者的论文被多读、多引、多给奖，初始小差距经正反馈指数放大。Dannefer 把它推广到生命历程：队列内的不平等随年龄发散（fan out），因为每个阶段的优势都兑现为下阶段的资源——教育差→初职差→晋升差→健康差，环环复利。DiPrete & Eirich 2006 年 ARS 综述把它整理成机制家族：不只是多的更多，还包括风险敞口的差异——同样的冲击对无缓冲者是灾难、对有缓冲者只是波折。图谱中它以产出边连「风化假说」——累积劣势×高努力应对是 Geronimus 生理超前老化的社会端；以耦合边接「分岔的命运」——McLanahan 的家庭资源极化正是 CAD 的家庭通道。边界：复利是隐喻级机制，具体载体（名声、信用、自信）因领域而异；发散预言对补偿性制度（再分配、回流教育）成立的社会要打折。",links:[{t:"Merton《The Matthew Effect in Science》DOI",u:"https://doi.org/10.1126/science.159.3810.56"},{t:"DiPrete & Eirich ARS 综述 DOI",u:"https://doi.org/10.1146/annurev.soc.32.061604.123127"}]},
{id:"kohli_mayer",aka:"科利 迈尔 生命历程制度化",domains:["work","mobility"],lever:0,cn:"生命历程制度化",en:"Institutionalized Life Course",scholar:"Martin Kohli",work:"Die Institutionalisierung des Lebenslaufs (KZfSS)",year:"1985",disc:"soc",school:"生命历程",core:"福利国家把人生标准化为'教育-就业-退休'三分结构；阶段边界本身是制度产物。",detail:"Kohli 1985 年的德文经典提出「生命历程的制度化」：福利国家不只是给钱，它把人生本身标准化成「教育→就业→退休」的三段结构——每段的边界（几岁入学、几岁退休）都是制度产物而非自然规律。人生于是被编排成时序规范：法定上学年龄定义了童年结束点，法定退休年龄制造了「老年」这个社会范畴，甚至「中年」也是制度切出来的。这个理论把「正常人生」去自然化：你以为该做的事很多是国家写好的剧本。它也解释了为什么生命历程比较研究必须带上体制变量——同样 25 岁，在不同福利体制下制度位置完全不同。图谱中它以耦合边连「社会时钟」——Neugarten 的准点/晚点压力正是制度化的主观面：三段制人生给文化时钟提供了制度骨架。边界：理论建立在德式福利国家经验上，弱国家与非正式经济社会的制度化程度低得多；去制度化（弹性退休、终身学习）正在松动三段论——但 Kohli 派反驳说松动本身也是新政策产物。",links:[{t:"EUI Cadmus 重印记录",u:"https://hdl.handle.net/1814/13766"}]},
{id:"neugarten",aka:"纽加顿 社会时钟",domains:["meaning","family","work"],lever:0,cn:"社会时钟",en:"Social Clock",scholar:"Bernice Neugarten",work:"Age Norms, Age Constraints",year:"1965",disc:"soc",school:"生命历程",core:"文化为事件定'最佳年龄'；'准点/晚点'是内化的规范压力，且按阶级分配。",detail:"Neugarten 1965 年这篇 AJS 创造了「社会时钟」概念：每个文化给人生事件标定「最佳年龄」——几岁该毕业、结婚、买房、升迁、退休，于是产生「准点」与「晚点」的评价压力。关键在于这个时钟是内化的：不需要别人提醒，「我 35 岁还没有……」的羞耻是自我执行的规范暴力；而且时钟按阶级分配——不同阶层对同一事件的「该有年龄」设定不同，迟到感也是阶级化的。这是「年龄作为社会规范」的奠基实证：年龄不只是计时器，还是道德秩序。图谱中它以谱系边连「文化死线」——Settersten & Hagestad 把社会时钟操作化成可测的文化 deadline 共识度；以耦合边接「生命历程制度化」——Kohli 的三段制人生是时钟的制度骨架，两者互为体制面与心理面。边界：1965 年的美国中产样本，时钟内容已大幅改写（Settersten 后来证明死线在松动）；内化机制的测量困难——准点焦虑有多少是规范压力、多少是实际资源计算，很难分开。",links:[{t:"AJS 原文 DOI",u:"https://doi.org/10.1086/223965"}]},
{id:"modell",aka:"莫德尔 成人转变",stages:["s2","s3"],domains:["family","work"],lever:0,cn:"成人标志变迁",en:"Transitions to Adulthood",scholar:"Modell, Furstenberg & Hershberg",work:"Social Change and Transitions to Adulthood",year:"1976",disc:"soc",school:"生命历程",core:"成年转变(离校/就业/离家/婚育)先被压缩为标准序列、后再次松动——延迟非线性。",detail:"Modell、Furstenberg & Hershberg 1976 年用历史人口学重建成人转变：把「长大成人」拆成五个可测事件——离校、就业、离家、结婚、生育——并追踪这个序列在 19 到 20 世纪的变化。发现一个非线性故事：先是「压缩」——工业化把这五件事挤进越来越窄、越来越标准的年龄窗口（战后达到极致，25 岁前全办完）；然后是「松动」——70 年代起事件再度分散、延迟、甚至逆序。他们的结论：成人转变的标准化本身是历史产物（避孕药、劳动市场、福利制度），不是什么自然节奏。图谱中它以谱系边连「延迟成人/制度撤退」——Modell 的压缩→松动历史骨架被 Furstenberg 续写为当代诊断：松动不是解放而是制度撤退后家庭各自为政。边界：资料主要是普查与城市档案，对边缘群体的转变模式覆盖差；五事件的选取带著核心家庭预设，当代多样化路径（不婚、绕道）让「延迟」本身都需要重新定标。",links:[{t:"J. of Family History 原文 DOI",u:"https://doi.org/10.1177/036319907600100103"}]},
{id:"settersten",aka:"塞特斯滕 文化死线",stages:["s2","s3"],domains:["meaning","family"],lever:0,cn:"文化死线",en:"Cultural Age Deadlines",scholar:"Richard Settersten",work:"What's the Latest? / Lives in Time",year:"1996/1999",disc:"soc",school:"生命历程",core:"年龄deadline是文化共识；去制度化时代deadline松动，下层失去规范轨道指引。",detail:"Settersten 把 Neugarten 的社会时钟操作化成可测变量：「文化死线」——访谈芝加哥成年人「男人/女人最晚应该几岁结婚、生子、完成学业」，测量的不只是有没有死线，还有共识度（多少比例的人给出同一个区间）与违规后果（错过死线会怎样）。发现：死线确实存在且有阶级分布——中上层的死线更晚（容许更长探索期）、底层更早；且死线的执行靠的不是正式制裁而是「别人会怎么想」的软压力。去制度化时代死线松动，受伤最重的是下层——规范轨道原本是他们唯一能依靠的脚本，松动后他们失去指引，上层却有资源自写剧本。图谱中它以谱系边接自「社会时钟」（时钟→可测死线），以耦合边接「成年转变推迟」——Billari 的欧洲比较证据（南欧 latest-late 模式）正是死线松动的跨国版本。边界：自报的规范共识与实际行为约束力之间有缺口；死线松动的阶级后果推论强于直接证据。",links:[{t:"The Gerontologist 原文 DOI",u:"https://doi.org/10.1093/geront/36.2.178"}]},
{id:"billari",aka:"比拉里 利夫布罗尔 成年转变推迟",stages:["s2","s3"],domains:["family","work"],lever:0,cn:"成年转变推迟",en:"Postponement of Transition",scholar:"Billari & Liefbroer",work:"Should I stay or should I go?",year:"2007/2010",disc:"soc",school:"生命历程",core:"离家/成家时序因福利体制分化(南欧latest-late-latest)——'晚'的机制因制度而异。",detail:"Billari 的研究线把「延迟」去单一化：成人转变的推迟不是全球一致的线性趋势，而是按福利体制分化的多种模式——他用 latest-late-latest 描述南欧（最晚离家、最晚结婚、最晚生育），对照北欧的早独立模式，指出「晚」在不同制度下机制完全不同：南欧是住房与劳动市场把青年绑在原生家庭（家庭作为福利替代），北欧是国家承担了转变成本所以早自立。与 Liefbroer 的 Demography 论文用荷兰面板证明年龄规范的预测力：感知的「该离家年龄」对实际离家时机有独立效应——规范不只是事后合理化。图谱中它以耦合边连「文化死线」——Settersten 的美国死线测量配上欧洲比较，证明死线松动的速率与形态由体制决定。边界：体制分类（Esping-Andersen 系）本身被批评过度整齐；离家/成家的测量依赖标准事件概念，对非传统路径（同居、再回流）的处理仍在发展中。",links:[{t:"Demography 原文 DOI",u:"https://doi.org/10.1353/dem.2007.0000"}]},
{id:"rutter_quint",aka:"拉特 鲁特 昆顿 链式风险",stages:["s1","s2","s3"],domains:["family","relation"],lever:1,gender:"f",cn:"链式风险与转机",en:"Turning Points / Chain of Risk",scholar:"Rutter & Quinton",work:"Parenting Breakdown",year:"1988",disc:"soc",school:"生命历程",core:"劣势经间接链式反应传导而非直接决定——支持性婚姻可断链。",detail:"Rutter & Quinton 追踪在机构长大的女孩到成年，发现劣势的传导不是命运决定而是「链式反应」：机构童年→缺乏良好关系的学习→青春期草率的伴侣选择→支持匮乏的婚姻→育儿崩溃——每一环只是提高下一环的机率，不直接锁死结局。这个间接链模型的革命性在于它同时证明链条可以断：关键转机（一段支持性婚姻、一个好学校经验）能截断传导——约四分之一机构长大的女性育儿良好，共同点是后来有过稳定支持关系。这是发展精神病学「风险与韧性」范式的奠基证据，也把代际传递从必然论改成机率论。图谱中它以耦合边连「knifing-off断档」——Rutter 的「链可断」命题正是 Sampson & Laub 转折点理论的前身：婚姻、工作、军队提供断链的结构机会。边界：样本是特定年代的英国机构女童，转机的选择效应（能进入好婚姻的人本来就不同）很难排除；链式机制是统计倾向，个体层面预测力有限。",links:[{t:"OBNB 书目记录 (Avebury 1988)",u:"https://obnb.uk/p10066106-parenting-breakdown-the-making-and-breaking-of-inter-generational-links"}]},
{id:"sampsonlaub",aka:"桑普森 劳布 断档",stages:["s3","s4"],domains:["family","work","relation"],lever:1,cn:"knifing-off断档",en:"Age-graded Social Control",scholar:"Sampson & Laub",work:"Crime in the Making / Shared Beginnings",year:"1993/2003",disc:"soc",school:"生命历程",core:"婚姻/稳定工作/军队提供knifing-off+监督+日常重构+身份机会→断档终生可能。",detail:"Sampson & Laub 重新分析了 Glueck 夫妇的波士顿少年犯资料（追到 70 岁），提出「年龄分级社会控制」理论：犯罪脱轨不是人格宿命，非正式社会控制的品质在人生各阶段都能改写轨迹——关键是 knifing-off 时刻：好的婚姻、稳定工作、军队服役这些事件把过去一刀两断（离开旧同侪、进入新日常结构、获得监督与身份改写的机会）。最强的发现是结构性转机的阶级分布：断档的可能性本身不公平——底层少年能碰上的好婚姻与稳定工作机会更少。图谱中它的边很实：耦合接「链式风险与转机」（Rutter 的链条模型是理论前身）、「认知转变/hooks」（Giordano 证明认知开放是 knifing-off 生效的心理前提）、「救赎脚本」（结构断档+叙事巩固=双机制）；张力边对「技能形成技术」——Heckman 的早期投资不可替代性 vs 终生转折点，两派在人生何时还能改上正面对峙。边界：转折点的选择效应（谁能获得好婚姻）很难与处理效应分开；非正式控制概念包罗太广，批评者要求拆出具体机制。",links:[{t:"Sampson 哈佛学者页著作列表",u:"https://sampson.scholars.harvard.edu/books-2"}]},
{id:"maruna",aka:"马鲁纳 救赎脚本",stages:["s3","s4"],domains:["meaning"],lever:1,cn:"救赎脚本",en:"Redemption Script",scholar:"Shadd Maruna",work:"Making Good",year:"2001",disc:"soc",school:"生命历程",core:"desister讲'真我本善'救赎叙事、persister讲定罪脚本——叙事是断档巩固机制。",detail:"Maruna 访谈利物浦的前科犯，发现成功脱离犯罪者（desisters）与持续犯罪者（persisters）的差异不在履历而在叙事：desister 讲「救赎脚本」——我本来就是好人，是被环境带坏，现在我找回真的自己并要回馈社会；persister 讲「定罪脚本」——我烂、世界烂、改不了。他的论点是叙事不只是回顾的修辞，而是断档的巩固机制：救赎脚本把改变写成自我实现的故事，把过去的罪责外化（环境）同时把未来的能动性内化（真我）——叙事结构本身就是维持改变的心理装置。图谱中它以耦合边接「knifing-off断档」（Sampson & Laub 给结构机会，Maruna 给巩固机制）与「叙事同一性/救赎自我」（McAdams 的 redemptive self 是同型构念）；谱系边接「标签理论」——Becker 的定罪标签→condemnation script，去标签→redemption，标签论的叙事化续写。边界：叙事方向可能是效果而非原因（改好了所以讲救赎故事）；横断访谈无法确立因果，纵贯证据后来才部分补上。",links:[{t:"APA《Making Good》",u:"https://www.apa.org/pubs/books/431645A"},{t:"电子书 DOI",u:"https://doi.org/10.1037/10430-000"}]},
{id:"giordano",aka:"焦尔达诺 认知转变",stages:["s2","s3"],domains:["meaning","relation"],lever:1,gender:"f",cn:"认知转变/hooks",en:"Hooks for Change",scholar:"Giordano et al.",work:"Gender, Crime, and Desistance",year:"2002",disc:"soc",school:"生命历程",core:"对改变开放→遇hooks→构想常规自我→身份转型；无认知准备则钩子钩不住。",detail:"Giordano 团队用女性少年犯的长期追踪资料提出「认知转变」理论，补上 Sampson & Laub 没讲的内部机制：环境给的「改变钩子」（hooks for change——婚姻、工作、宗教社群）不会自动生效，要先有四步认知工作——对改变开放（厌倦旧生活）、遇上钩子、把钩子与一个「常规自我」的想像连起来、最后把旧身份定义为不再是我。没有认知准备，钩子钩不住：同样的结婚机会，有人断档有人把配偶也拖下水。这个理论把脱离犯罪从好运气改写成主体准备×结构机会的乘积，也解释了为什么女性脱轨者的路径常绕过婚姻——她们的钩子常是母职与宗教。图谱中它以耦合边连「knifing-off断档」——两家文献互补：Sampson & Laub 给结构面，Giordano 给认知前提，合起来是「机会×准备」的完整断档模型。边界：叙事资料的回溯性（受访者事后讲的开放可能是事后合理化）；四步序列的实证分界模糊，被批评更像诠释框架而非可证伪模型。",links:[{t:"AJS 原文 DOI",u:"https://doi.org/10.1086/343191"}]},
{id:"furstenberg",aka:"弗斯滕伯格 延迟成人 制度撤退",stages:["s2","s3"],domains:["family","work","money"],lever:0,cn:"延迟成人/制度撤退",en:"Delayed Transition",scholar:"Frank Furstenberg",work:"Growing Up Is Harder to Do / Frontier of Adulthood",year:"2004/2005",disc:"soc",school:"生命历程",core:"成人转变拉长=制度撤退：去工业化+文凭通胀+家庭支持私有化，家庭转移支付成为隐形分层。",detail:"Furstenberg 观察到成人转变在美国已系统性延迟：「长大成人」从 25 岁前完成的压缩序列，被拉长成 25-35 岁的旷野期——而他的关键判断是这不是「不想长大」而是制度撤退：去工业化砍掉高中学历的稳定工作、文凭通膨把合格线推到硕士、同时国家与雇主撤退，把转变成本私有化给家庭。于是「家庭能供孩子啃老多久」成了隐形分层变量：中产家庭的成年过渡期靠父母资助完成，底层青年被直接推入成人世界。图谱中它承接两条谱系：接「生命历程五原则」（Elder 范式的当代应用）与「成人标志变迁」（Modell 的压缩→松动史被续写成制度撤退史）；耦合边接「分岔的命运」——延迟使家庭转移支付成为分层机制，正是 McLanahan 记录的两条阶级轨迹。边界：「制度撤退」作为总括解释有点大，具体机制（住房、教育债、劳动市场各自权重）后续研究在拆分；美国中心视角下，欧洲延迟的机制不同（Billari 的体制比较是必要对照）。",links:[{t:"Contexts 原文 DOI",u:"https://doi.org/10.1525/ctx.2004.3.3.33"}]},
{id:"silva",aka:"席尔瓦 受挫的成年 功亏一篑",stages:["s2","s3"],classes:["c1"],domains:["meaning","mobility"],lever:0,cn:"受挫的成年",en:"Coming Up Short",scholar:"Jennifer Silva",work:"Coming Up Short",year:"2013",disc:"soc",school:"生命历程",core:"工人阶级无'emerging adulthood'：制度标志不可得→转向治疗性成年标志(戒断/情绪自律)。",detail:"Silva 访谈 100 个工人阶级青年，发现 emerging adulthood 对他们是残酷的反讽：没有资本探索、没有制度供给的缓冲期，教育-就业-独立居住的标准成人标志不可得——他们的成年不是「到达」而是「受挫」。于是产生 Silva 最尖锐的发现：当制度标志缺席，工人阶级转向「治疗性成年标志」——成年被重定义为对内心恶魔的克服：戒断、走出虐待关系、情绪自律、学会不怨恨。成长叙事从「我拿到了什么」变成「我熬过了什么」。这种转向的代价是政治性的：治疗叙事把结构失败私有化为个人心理工作，工人阶级的不满被安全地排进自助话语。图谱中它以耦合边接「志向持平」（MacLeod 的幻灭→治疗性成年的代际续篇）、「阶级隐痛」（治疗性成年=隐痛的当代形态）、「叙事同一性/救赎自我」（阶级化的叙事体裁分化）；张力边直攻「成人初显期」——工人阶级根本没有 EA，Arnett 的概念被证明是阶级特权的产物。边界：访谈集中在两个去工业化城镇；治疗性转向是否为新现象还是被记录得更好了，有争议。",links:[{t:"Oxford Academic《Coming Up Short》",u:"https://doi.org/10.1093/acprof:oso/9780199931460.001.0001"}]},
{id:"mare",aka:"梅尔 教育转型",stages:["s1","s2"],domains:["mobility"],lever:0,cn:"教育转型模型",en:"Educational Transitions",scholar:"Robert Mare",work:"Social Background and School Continuation",year:"1980",disc:"soc",school:"教育不平等",core:"把教育获得拆成条件性升学决策序列——扩张提高总量但每个闸门的筛选维持。",detail:"Mare 1980 年的 JASA 论文把「教育获得」从一个总量改写成一串条件性决策：不是「家庭背景→最终学历」的单一路径，而是每个升学闸门（升初中→升高中→升大学→研究所）分别计算出身效应——关键发现是出身效应沿闸门递减：越早的转换点阶级筛选越狠，能走到后面闸门的人已经是被选过的。这个「教育转换模型」让不平等研究第一次可以问「筛选发生在哪个关卡」，也预言了扩张悖论：教育总量扩张可以推高全民水平，但只要每个闸门的筛选强度不变，不平等只是换了楼层。图谱中它以谱系边连「最大化维持不平等」——Raftery & Hout 把 Mare 的模型提炼成 MMI 命题：优势阶级先饱和、扩张才惠及下层，直接从转换点逻辑推出。边界：闸门递减的解释有争议（到底是选择效应、真实衰减还是测量假象——Boudon 与 Cameron/Heckman 对此交火多年）；模型把每个转换当独立决策，低估早期轨道对后期偏好的塑造。",links:[{t:"JASA 原文 (JSTOR DOI)",u:"https://doi.org/10.2307/2287448"}]},
{id:"mmi",aka:"拉夫特里 豪特 最大化维持不平等",stages:["s1","s2"],domains:["mobility"],lever:0,cn:"最大化维持不平等",en:"Maximally Maintained Inequality",scholar:"Raftery & Hout",work:"Maximally Maintained Inequality",year:"1993",disc:"soc",school:"教育不平等",core:"优势阶级在某层级饱和前，扩张不惠及下层——爱尔兰实证。",detail:"Raftery & Hout 用爱尔兰 1921-75 数据提出「最大化维持不平等」（MMI）命题：教育扩张不会自动平等化——因为优势阶级会先把自己的参与率推到饱和，在那之前扩张的每个新增名额都被他们吃掉；只有当优势阶级在某层级已经「人人都有」之后，继续扩张才开始惠及下层。所以不平等在该层级饱和点之前维持最大化——这是 Mare 转换模型的规范化版本：闸门不是平等的障碍数，而是优势阶级先到先得的机制。爱尔兰的实证：中学扩张确实缩小了整体差距，但只在优势阶级接近饱和之后。图谱中它以谱系边接自「教育转型模型」（闸门逻辑的命题化），放出「有效维持不平等」——Lucas 把 MMI 精炼为质量维版本；耦合边接「持续不平等13国」——Shavit & Blossfeld 的跨国比较是 MMI 最大的支持证据集。边界：MMI 对「为什么下层不抢」的需求端机制著墨少（Breen & Goldthorpe 补上了理性计算）；饱和的测量阈值随定义浮动，且对质量维不平等（EMI）成立后 MMI 的适用范围限缩到数量维。",links:[{t:"Sociology of Education 原文 (JSTOR DOI)",u:"https://doi.org/10.2307/2112784"}]},
{id:"emi",aka:"卢卡斯 有效维持不平等",stages:["s1","s2"],domains:["mobility"],lever:0,cn:"有效维持不平等",en:"Effectively Maintained Inequality",scholar:"Samuel Lucas",work:"Effectively Maintained Inequality",year:"2001",disc:"soc",school:"教育不平等",core:"数量普及后，优势转向质量维(学术轨/院校层次)——分层换维永续。",detail:"Lucas 2001 年的 EMI 命题解决 MMI 解决不了的问题：如果某教育层级已经普及（优势阶级饱和、下层也进来了），不平等怎么还活著？答案是换维度——优势阶级从「数量」撤退到「质量」：大家都有高中文凭之后，争的是哪个轨道（学术 vs 职业）、哪所学校（菁英 vs 社区）、什么内容（微积分 vs 生活数学）。他用美国高中追踪数据证明：即使控制升学与否，出身依然显著预测轨道位置——不平等被「有效维持」在质量维上。这个命题解释了为什么教育平等化政策总像打地鼠：堵了数量缺口，优势就转场到质量。图谱中它以谱系边接自「最大化维持不平等」（数量饱和→质量维的逻辑续推），耦合边接「文凭社会」（Collins 的文凭通膨正是质量维竞争的动力）、「分轨制」（校内分轨是质量维的执行器）、「血统/精英招聘」（质量维竞争的雇用端兑现）。边界：质量维的测量比数量维困难得多（轨道、学校层级的操作化因国而异）；理论预设优势阶级总能找到新维度，接近不可证伪——批评者说它把不平等永续变成公理而非假说。",links:[{t:"AJS 原文 DOI",u:"https://doi.org/10.1086/321300"}]},
{id:"shavit",aka:"沙维特 布洛斯菲尔德 持续不平等",stages:["s1","s2"],domains:["mobility"],lever:0,cn:"持续不平等13国",en:"Persistent Inequality",scholar:"Shavit & Blossfeld",work:"Persistent Inequality",year:"1993",disc:"soc",school:"教育不平等",core:"13国教育大扩张中出身-获得关联几乎不变；唯激进平等化政策能缩小。",detail:"Shavit & Blossfeld 1993 年主编的《Persistent Inequality》是教育不平等比较研究的里程碑：13 个工业国的统一设计分析发现，整个 20 世纪的教育大扩张中，「出身→教育获得」的关联几乎没有衰减——扩张提高了所有人的均值，但相对位置几乎原封不动。唯二的例外是瑞典与荷兰，两国靠的不是教育改革而是整体性的激进平等化政策（压平收入差、强力福利）——教训是教育不平等不在教育系统里治。这个「持续不平等」发现是 MMI/EMI 家族最硬的跨国证据。图谱中它以耦合边连「最大化维持不平等」——13 国模式正是「优势饱和前扩张不惠及下层」的最大实证支持。边界：13 国比较的队列跨度与数据品质参差（各国普查与调查口径不同）；「关联几乎不变」在后续 Breen 等人的更新中发现部分国家确有缓慢松动，「持续」的强度因测量口径而异。",links:[{t:"Tel Aviv University 研究记录",u:"https://cris.tau.ac.il/en/publications/persistent-inequality-changing-educational-attainment-in-thirteen/"}]},
// ── 补入：微观互动/网络/标签线（评审增补） ──
{id:"goffman",aka:"戈夫曼 拟剧论 污名 日常生活中的自我呈现",domains:["relation","meaning"],lever:0,cn:"拟剧论/污名",en:"Presentation of Self / Stigma",scholar:"Erving Goffman",work:"Presentation of Self 1959 / Stigma 1963",year:"1959/1963",disc:"soc",school:"微观互动",core:"互动秩序要求持续的印象管理；'受损身份'被互动系统惩罚——阶层羞辱的微观力学。",detail:"Goffman 把日常互动当成有技术要求的工作：《日常生活中的自我呈现》提出拟剧论——每场相遇都是表演，人持续管理别人对自己的印象（前台、后台、道具、剧班），而互动秩序是脆弱的公共产品，需要所有人合作维持「事情如常」的表象。《Stigma》补上惩罚面：带著「受损身份」（身体缺陷、犯罪记录、阶级标记）的人被互动系统系统性地扣分——他们要在「藏」（资讯管理）与「亮」（身份承认）之间做不可能的选择。这两本书给出阶级羞辱的微观力学：阶级不只是资源差，它在每次互动中被重新执行——谁能放松、谁要管理。图谱中它以谱系边连「阶级隐痛」（受损身份的互动机制→阶级痛感的微观基础），耦合边接「道德-文化边界」（印象管理×道德划界的接口）。边界：戏剧隐喻把互动读得太像策略表演，低估了习惯与体化；分析停在互动层，对「谁制定剧本」的权力问题刻意留白——布迪厄派批评它微观精致但结构盲。",links:[{t:"Anchor/PRH《The Presentation of Self》",u:"https://www.penguinrandomhouse.com/books/708488/the-presentation-of-self-in-everyday-life-by-erving-goffman/"},{t:"S&S/Touchstone《Stigma》",u:"https://www.simonandschuster.net/books/Stigma/Erving-Goffman/9780671622442"}]},
{id:"wilson",aka:"威尔逊 真正弱势者 真正的穷人",stages:["s3","s4"],classes:["c1"],domains:["work","family","money"],lever:0,cn:"真正劣势者",en:"The Truly Disadvantaged",scholar:"William J. Wilson",work:"The Truly Disadvantaged",year:"1987",disc:"soc",school:"城市贫困",core:"去工业化→黑人男性失业→婚配池枯竭+家庭结构瓦解——城市贫困的结构性而非文化性解释。",detail:"Wilson 1987 年的《The Truly Disadvantaged》是城市贫困研究的转向之作：他反对两边的标准答案——右派的「文化缺陷」（穷人有坏价值观）与左派的「纯种族歧视」——提出结构性解释：去工业化抽走内城制造业工作→黑人男性失业率暴涨→「可婚配男性池」枯竭→单亲家庭率上升→社区中产也搬离→剩下的人失去的不只是工作还有社会组织的支架（社会隔离与集中效应）。链条是经济的，产出才是「类文化的」（失业后的时间结构崩坏、地下经济）。这本书逼整个领域把因果箭头调回结构端。图谱中它以谱系边连「绝望死亡」——去工业化→男性失业→家庭瓦解链条正是 Case & Deaton 三十年后量化的上游；以耦合边接「分岔的命运」（男性失业→婚配池枯竭→家庭结构分岔）与「城市放逐者/先进边缘」（Wacquant 把真正劣势者更新为领地污名+国家撤退的先进边缘版本）。边界：「婚配池枯竭」对单亲率的解释份额被后续研究下调；他刻意淡化种族歧视的策略被批评为低估了歧视本身的独立作用。",links:[{t:"U Chicago Press《The Truly Disadvantaged》",u:"https://www.press.uchicago.edu/ucp/books/book/chicago/T/bo13375722.html"}]},
{id:"putnam",aka:"帕特南 独自打保龄 我们的孩子",stages:["s1","s2"],domains:["relation","family","mobility"],lever:0,cn:"社会资本衰落/我们的孩子",en:"Bowling Alone / Our Kids",scholar:"Robert Putnam",work:"Bowling Alone 2000 / Our Kids 2015",year:"2000/2015",disc:"soc",school:"社会资本",core:"公民参与与社区网络持续衰减；《我们的孩子》展示阶级×童年的机会鸿沟代际复制。",detail:"Putnam 用两本书写了美国社会资本的衰落史：《独自打保龄》用数百组数据证明从 1960 年代起公民参与、社区网络、非正式社交全面衰退——保龄球联盟消失成了连带瓦解的标志性隐喻，他区分 bonding（同质内部）与 bridging（异质桥梁）两种资本，衰落的是后者；《我们的孩子》把同一把尺对准阶级×童年：家乡 Port Clinton 的 1959 届同窗几乎人人向上流动，半世纪后同镇孩子的机会鸿沟按父母教育线划开——社会资本的衰退正是机会不平等代际复制的通道。图谱中它以谱系边连「社会资本(创造人力资本)」——这条边把 Coleman 的功能定义与 Putnam 的全民衰减测量锁成同一条学术线；以耦合边接「社会整合-死亡率」——资本衰落的暴露增加对应 Berkman 的死亡率通路。边界：衰退的时间点与「谁的衰退」被批评（部分参与只是转了形式）；社会资本的存量隐喻模糊了它作为关系过程的本质；Our Kids 被批评乡愁化战后异常态。",links:[{t:"S&S《Bowling Alone》",u:"https://www.simonandschuster.com/books/Bowling-Alone-Revised-and-Updated/Robert-D-Putnam/9780743219037"},{t:"S&S《Our Kids》",u:"https://www.simonandschuster.com/books/Our-Kids/Robert-D-Putnam/9781476769905"}]},
{id:"coleman",aka:"科尔曼 社会资本",stages:["s1","s2"],domains:["relation","family"],lever:0,cn:"社会资本(创造人力资本)",en:"Social Capital in Creation of Human Capital",scholar:"James Coleman",work:"AJS 94",year:"1988",disc:"soc",school:"社会资本",core:"功能定义：封闭网络中的义务/期望/信息渠道/规范——人力资本形成的社会结构条件。",detail:"Coleman 1988 年这篇 AJS 给「社会资本」下了功能定义：它不是某种东西，而是社会结构中「让行动成为可能」的资源——三种形态：义务与期望（你帮我一次我就欠你）、资讯渠道（从关系网获得非正式资讯）、规范（共同标准的执行）。他的机制核心是「封闭性」：当每个人都认识彼此的所有人（家长认识孩子朋友的所有家长），义务、资讯与规范才能被执行——他用天主教学校辍学率更低做例证：不是学校好，是家长间的封闭网络把人力资本投资的监督成本摊平了。这是把社会结构塞回理性选择框架的经典操作。图谱中它以谱系边接「社会资本衰落/我们的孩子」——Coleman 的功能定义与 Putnam 的全民衰减测量属同一条学术线；耦合边接「协作培养/自然成长」（封闭网络正是 Lareau 中产教养模式的结构条件）与「消逝的美国梦/机会地图」（社会资本是 Chetty 流动性预测的关键变量）。边界：功能定义被批评为循环（凡有用的都叫社会资本）；封闭性的收益依赖网络内容——封闭的帮派网络也执行规范，方向可以向下。",links:[{t:"AJS 原文 DOI",u:"https://doi.org/10.1086/228943"}]},
{id:"sennett_corrosion",aka:"森尼特 品格的腐蚀 没有面目的人",stages:["s3","s4"],classes:["c2"],domains:["work","meaning"],lever:0,cn:"品格的腐蚀",en:"The Corrosion of Character",scholar:"Richard Sennett",work:"The Corrosion of Character",year:"1998",disc:"soc",school:"阶级经验",core:"弹性资本主义要求'无长期'：短期化侵蚀忠诚/承诺/叙事自我——中产品格的时间性损伤。",detail:"Sennett 1998 年的《品格的腐蚀》诊断弹性资本主义对人格的时间性伤害：「无长期」的新经济要求短期团队、随时重组、把每个人都当项目——这侵蚀的是需要时间才能累积的品格：忠诚、承诺、对自己人生叙事的连贯感。他用访谈对比父子两代：父亲在 IBM 官僚制里有稳定轨道（僵化但有叙事），儿子在弹性经济里有自由（但无法把碎片编成有意义的人生故事）——「品格腐蚀」不是变坏，而是失去把生命当成连贯作品的可能性。图谱中它以耦合边接「流动现代性/有缺陷的消费者」（Bauman 诊断的人格面：短期化=流动性的人格代价）与「叙事同一性/救赎自我」（短期化侵蚀可叙述的连续自我，McAdams 的结构面）。边界：访谈与印象式论证，缺乏系统数据；「品格」概念带著怀旧温度（官僚制时代的稳定对女性与少数族裔未必是天堂）；它描述的是中产知识工作者的痛，底层的短期化是更粗糙的生存问题。",links:[{t:"Norton《The Corrosion of Character》",u:"https://wwnorton.com/books/9780393319873"}]},
{id:"granovetter",aka:"格兰诺维特 格拉诺维特 弱关系",stages:["s3","s4"],domains:["work","relation","mobility"],lever:1,cn:"弱关系的力量",en:"Strength of Weak Ties",scholar:"Mark Granovetter",work:"AJS 78",year:"1973",disc:"soc",school:"社会资本",core:"新信息经弱关系而非强关系流动——工作机会的网络结构通道，阶级再生产的信息面。",detail:"Granovetter 1973 年这篇 AJS（社会科学被引最多的论文之一）证明一个反直觉：找工作靠的不是挚友而是点头之交。逻辑：强关系（亲友）的资讯圈与你高度重叠——他们知道的你基本也知道；弱关系（偶尔联系的旧同事、朋友的朋友）才是通往异质资讯圈的桥——新工作机会、新市场情报从「桥」流入，所以弱关系的强度在于它们是结构洞的跨越者。这给「谁找到工作」提供了网络结构解释，也把微观互动与宏观分层接通：机会网络本身是阶级资产。图谱中它以耦合边接「赞助/竞争流动」（弱关系是工作资讯流动的微观通道，流动的网络机械面）与「消逝的美国梦/机会地图」（Chetty 的跨阶级连通性数据是弱关系逻辑的大数据兑现——跨阶友谊是流动性的最强预测因子之一）。边界：原研究的波士顿郊区专业人士样本，对底层劳动市场（内部介绍制、工地门口招工）适用性打折；「弱」的操作化（联系频率）粗糙；弱关系理论预设资讯是稀缺品，在岗位资讯公开化的时代部分失效。",links:[{t:"AJS 原文 DOI",u:"https://doi.org/10.1086/225469"}]},
{id:"merton_strain",aka:"默顿 失范 结构紧张",domains:["money","work","meaning"],lever:0,cn:"结构紧张/失范类型",en:"Social Structure and Anomie",scholar:"Robert Merton",work:"ASR 3(5)",year:"1938",disc:"soc",school:"微观互动",core:"文化目标×制度化手段脱钩→创新/仪式主义/退却/反叛四类适应——阶层压力的适应类型学。",detail:"Merton 1938 年的《社会结构与失范》把涂尔干的失范改写为结构性紧张：文化给所有人定了同一个目标（美国梦=金钱成功），但制度化手段（好工作、教育通道）按阶级配给——当目标与手段脱钩，个人在「接受目标/接受手段」的 2×2 里选择适应方式：遵从（都接受）、创新（要目标不要手段→犯罪、投机）、仪式主义（放弃目标死守规则→螺丝钉中产）、退却（都放弃→隐士、瘾君子）、反叛（两者都换→革命）。这个类型学的天才在于把越轨定位为「结构产生的正常反应」而非人格异常——底层的高越轨率不是坏人多，而是被合法手段排除的人对同一个成功指令的理性回应。图谱中它以谱系边接「自杀论/失范」（涂尔干概念的美国社会学化），耦合边接「学做工/反学校文化」（创新/退却/反叛=反学校文化的适应类型——lads 的抵抗是反叛的未完成形态）。边界：类型学对中间态与混合型（大多数人）归类困难；「文化目标单一性」在多元社会已不成立；它解释结构压力好过解释具体选择（为何此人创新彼人退却，理论内无法回答）。",links:[{t:"ASR 1938 原文 (JSTOR DOI)",u:"https://doi.org/10.2307/2084686"}]},
{id:"becker_outsiders",aka:"贝克尔 标签理论 局外人",domains:["relation","meaning"],lever:0,cn:"标签理论",en:"Labeling Theory / Outsiders",scholar:"Howard Becker",work:"Outsiders",year:"1963",disc:"soc",school:"微观互动",core:"越轨不是行为属性而是规则制定者贴标签的结果——学校纪律标签→身份螺旋。",detail:"Becker 1963 年的《Outsiders》是标签理论的奠基文本：越轨不是行为的内在属性，而是「规则被制定、被执行、被贴在特定人身上」的社会过程的产物——同一个动作（大麻、逃学、性交易），被叫什么取决于谁有权定义与谁被抓住。他追踪标签的后果链：一旦被贴上「越轨者」，主身份（master status）覆盖其他一切，越轨变成自我实现——被当成坏学生的孩子被赶出正常轨道，只能在越轨群体里重建身份，于是「初级越轨」被制度加工成「次级越轨」。这个理论把犯罪学的提问从「他为什么越轨」翻成「社会为什么把这叫越轨、标签怎么运作」。图谱中它以谱系边连「救赎脚本」——Becker 的定罪标签→condemnation script，去标签/重新叙事→redemption，标签论被 Maruna 叙事化续写。边界：对初级越轨的起因解释弱（标签从哪来）；被批评为越轨者开脱（受害者去哪了）；标签的不可逆性在现代去标签化实践（去罪化、record expungement）中被部分证伪。",links:[{t:"S&S《Outsiders》",u:"https://www.simonandschuster.com/books/Outsiders/Howard-S-Becker/9781982106225"}]},
{id:"wacquant",aka:"瓦康 华康德 城市放逐者",classes:["c1"],domains:["money","relation","work"],lever:0,cn:"城市放逐者/先进边缘",en:"Urban Outcasts",scholar:"Loïc Wacquant",work:"Urban Outcasts",year:"2008",disc:"soc",school:"城市贫困",core:"去工业化+国家撤退+领地污名→'先进边缘'：贫困不再经工厂而经空间隔离再生产。",detail:"Wacquant 把贫困研究从「人群」转到「空间」：《城市放逐者》比较芝加哥南区与巴黎郊区，发现 1980 年代后出现「先进边缘」的新机制——贫困不再经由工厂纪律再生产，而是经由空间隔离：去工业化让工作离开、国家撤退让福利与警力变成惩罚性存在、领地污名（住在某区本身成为履历污点）让居民被困在贬值地段里。他的核心概念「领地污名」：邮递区号成了阶级标记，被雇主、警察与房贷系统读取；而这个污名又迫使居民发展出抵抗性空间实践（拳击馆作为道德经济）。图谱中它以谱系边接「真正劣势者」——Wacquant 把 Wilson 的去工业化模型加上领地污名与国家撤退两个维度，更新为先进边缘版本。边界：美法双案例的对比设计让机制归因复杂（哪个是普遍机制、哪个是国别变异）；「先进边缘」与 Wilson 的 underclass 概念的区分度被批评为术语更新大于实质突破。",links:[{t:"Polity《Urban Outcasts》",u:"https://www.politybooks.com/bookdetail?book_slug=urban-outcasts-a-comparative-sociology-of-advanced-marginality--9780745631240"},{t:"作者官网",u:"https://loicwacquant.org/urban-outcasts-a-comparative-sociology-of-advanced-marginality/"}]},
{id:"desmond",aka:"德斯蒙德 扫地出门 下一个家在何方",stages:["s1","s3","s4"],classes:["c1"],domains:["money","family","work"],lever:0,cn:"扫地出门",en:"Evicted",scholar:"Matthew Desmond",work:"Evicted",year:"2016",disc:"soc",school:"城市贫困",core:"驱逐不是贫困的结果而是原因：住房不稳定→学校/工作/家庭连环崩塌——稀缺的最具体机制。",detail:"Desmond 的《扫地出门》把贫困研究从「缺钱」转到「缺屋」：密尔沃基民族志加创驱逐法庭数据，证明驱逐不是贫困的结果而是原因——被赶出住房引发连锁崩塌：孩子转学、工作丢失、家庭分散、心理健康崩溃、信用记录留下污点使下次租房更难，于是住房不稳定成为贫困自我复制的最具体机制。他还揭露了驱逐的政治经济：内城房东的利润率远高于富裕区（坏房子加高周转加租客无议价力），「破旧房产」是系统性剥削的生意模式而非市场失败。图谱中它以耦合边接「稀缺认知税」（驱逐=带宽占用的最极端机制：住房不稳让所有长期决策瘫痪）与「脆弱家庭」（住房轴是家庭解体的物质引爆点）。边界：密尔沃基单城民族志加驱逐记录，美国住房体制的特异性（公租房少、私租主导）使外推需调整；批评者指出他对租客自身因素（吸毒、犯罪）的处理偏轻，且房东侧的策略也有合法面——但这恰恰是他的论点：系统让「合法」与「剥削」同义。",links:[{t:"PRH/Crown《Evicted》",u:"https://www.penguinrandomhouse.com/books/247816/evicted-by-matthew-desmond/"},{t:"官方书网",u:"https://evictedbook.com/"}]},
// ── 补入：经典宏观理论与生命历程扩展 ──
// ── 古典社会学 ──
{id:"tonnies",cn:"共同体与社会",en:"Gemeinschaft und Gesellschaft",scholar:"Ferdinand Tönnies",work:"《共同体与社会》",year:"1887",disc:"soc",school:"古典社会学",core:"共同体的本质意志(血缘/地缘/精神)vs社会的选择意志(契约/工具)——现代化=共同体被社会置换的凉薄进程。",detail:"滕尼斯1887年把人类联结劈成两种理想型：共同体是「本质意志」的有机生长——血缘（家族）、地缘（邻里）、精神（友谊），成员在共享习俗与情感中天然属于彼此；社会是「选择意志」的人工建构——契约、公司、市场，人为了目的暂时结合、随时可撤。他的判断带着温度：现代化就是共同体不断被社会置换，而置换有代价——人得到自由、失去归属，关系变得高效但凉薄。这个二分是后世所有「传统vs现代」叙事的语法源头：涂尔干的机械/有机团结、韦伯的理性化、当代的共同体消亡诊断都从这里分叉。图谱中它以谱系边连「分工与有机团结」——涂尔干把怀念性的二分改写成功能分析：共同体不是失去的天堂，而是整合的一种技术形态；耦合边接「社会资本衰落/我们的孩子」（Putnam的保龄球馆衰退=共同体消亡的量化续写）与「社会整合-死亡率」（整合的保护效应=共同体的生理收益）；也接「实在的社会建构」——共同体的「天然归属感」正是被体验为自然的nomos。边界：滕尼斯自承二型是纯粹型、现实永远混合；把「社会」读成纯粹的恶是浪漫主义残留——契约社会也长出了新团结（工会、公民社会）。",links:[{t:"Deutsches Textarchiv 1887原版全文",u:"https://deutschestextarchiv.de/book/show/toennies_gemeinschaft_1887"}],aka:"滕尼斯 礼俗社会 法理社会 共同体与社会",domains:["relation","meaning"],lever:0},
// ── 系统功能主义 ──
{id:"parsons",cn:"结构功能主义/AGIL",en:"The Social System",scholar:"Talcott Parsons",work:"《社会系统》The Social System",year:"1951",disc:"soc",school:"系统功能主义",core:"行动=人格+社会+文化三系统互渗透；AGIL四功能；角色互补把人格与系统咬合——秩序问题的主流答案。",detail:"帕森斯把韦伯与涂尔干熔成一个总体框架：行动是个体在规范约束下朝向目标的定向，而社会系统靠四个功能项维持——AGIL：适应（经济）、目标达成（政治）、整合（法律与共同体）、模式维持（家庭与教育）。他的枢纽概念是「角色」：人格系统与社会系统通过期望互补咬合——我期待你按规范演、你期待我按规范演，制度化就是这两套期望的稳定互锁，社会化的内容就是把角色期望写进人格。这个框架统治了五十年代美国社会学，也孵化了分层与教育研究：学校在图式中是模式维持与适应的接口机构。图谱中它以谱系边连「功能主义分层」——Davis & Moore正是该体系在分层问题上的直接应用：位置按功能重要性排序、报酬按排序配给；张力边对「阶级剥削论」——冲突派指控功能主义把支配写成需求：AGIL从不回答「谁的功能、对谁适应」；耦合边接「生命历程制度化」——Kohli的制度化人生可视为模式维持功能的时间面。边界：解释秩序强于解释变迁与冲突，1968年后被冲突论与互动论围攻退潮；但「角色互补」与「制度化」概念已渗入一切后续理论。",links:[{t:"OBNB书目记录 (Routledge 1991)",u:"https://obnb.uk/p11967311-the-social-system"}],aka:"帕森斯 结构功能主义 AGIL 社会系统",domains:["relation","meaning","family"],lever:0},
{id:"luhmann",cn:"社会系统论/自创生",en:"Social Systems / Autopoiesis",scholar:"Niklas Luhmann",work:"Soziale Systeme《社会系统》",year:"1984",disc:"soc",school:"系统功能主义",core:"社会=以沟通为基本单位的自创生系统；功能分化取代阶层成首要分化——不平等被分配到各子系统。",detail:"卢曼把社会学的基本单元从「人」换成「沟通」：社会系统不是由人而是由沟通构成的自创生系统——沟通只接得上沟通，人（心理系统）是系统的环境而非成分。这个激进操作推出冷峻结论：现代社会的首要结构不是阶层而是功能分化——经济、政治、法律、科学、教育各自以二元代码运转（支付/不支付、合法/非法、真/不真），没有总指挥中心。对阶级研究这是双刃的：阶层不再被视为统摄一切的总结构，但各子系统的准入门槛仍按阶级事实分配——教育代码的真/不真、经济代码的支付/不支付，各自关卡叠起来就是阶层的去中心化版本。图谱中它以张力边连「阶级剥削论」与「功能主义分层」——冲突派认为功能分化论把「谁支配」蒸发成系统语法；耦合边接「治理术/自我企业家」（系统的自我描述=治理话语的自我生产）与「文化工具箱」（各子系统供应可装配的代码剧目）。边界：抽象度极高、可证伪性弱；「人只是环境」的设定让它处理经验不平等时必须绕道转译。",links:[{t:"Stanford UP《Social Systems》",u:"https://www.sup.org/books/sociology/social-systems"}],aka:"卢曼 社会系统 自创生 功能分化",domains:["meaning","relation"],lever:0},
// ── 过程社会学 ──
{id:"elias",cn:"文明进程/宫廷社会",en:"The Civilizing Process / The Court Society",scholar:"Norbert Elias",work:"《文明的进程》Über den Prozess der Zivilisation",year:"1939/1969",disc:"soc",school:"过程社会学",core:"暴力与税收垄断→互赖网络加密→外部强制沉淀为自我克制；宫廷礼仪=阶级惯习的历史原型。",detail:"埃利亚斯1939年的《文明的进程》用礼仪手册史证明「文明」是结构过程的副产品：国家逐步垄断暴力与税收→武力竞争被淘汰→人际互赖网络加密→外部强制沉淀为自我克制——擤鼻涕、餐桌礼仪、情绪控制，从宫廷规矩变成「天生如此」的第二自然。配套的《宫廷社会》更狠：凡尔赛的礼仪不是繁文缛节而是权力技术——贵族用礼节精确排位，谁能自如执行复杂仪式谁就保住位置，失仪即失势。关键立场是「过程性」：文明没有设计者，是长期无计划的合力方向，且方向可以倒退（他亲历过文明倒退）。图谱中它以谱系边连「惯习·场域·资本」——布迪厄自认惯习概念深承埃利亚斯：宫廷的礼节竞争是场域与惯习的历史原型；耦合边接「特权/从容」（Khan的从容=礼节技术的当代形态）与「拟剧论/污名」（印象管理的宫廷起源）；张力边对「功能主义分层」——过程论拒绝功能归因。边界：材料限于欧洲宫廷史，非西方「文明化」路径需重写；长时段解释力强但礼仪扩散的中短期机制常留白。",links:[{t:"Wiley-Blackwell《The Civilizing Process》",u:"https://www.wiley.com/en-us/The+Civilizing+Process%3A+Sociogenetic+and+Psychogenetic+Investigations%2C+2nd+Edition-p-9780631221616"}],aka:"埃利亚斯 埃里亚斯 文明的进程 宫廷社会",classes:["c3"],domains:["relation","meaning"],lever:0},
// ── 结构与能动性 ──
{id:"giddens",cn:"结构化理论",en:"Structuration Theory",scholar:"Anthony Giddens",work:"《社会的构成》The Constitution of Society",year:"1984",disc:"soc",school:"结构与能动性",core:"结构二重性：结构既是行动媒介又是行动结果；结构不只约束也使能——结构vs能动的和解方案。",detail:"吉登斯1984年的《社会的构成》要终结结构与能动的百年对撕，武器是「结构二重性」：结构不是外在于人的框架——它既是行动的媒介（你用规则才能行动）又是行动的结果（行动再生产规则）；结构同时是约束与使能，就像语法既限制你能说什么又使你能说。由此微观/宏观的隔墙被拆掉：日常实践的例行化在时空中不断重演，本身就是结构的生产现场；能动性是「本可以别样作为」的能力，不是与结构对立的飞地。对生命历程的含义直接：人生不是沿固定轨道滑动，而是行动者在例行实践中持续重写的轨迹——这与Elder的能动性原则是本体论盟友。图谱中它以耦合边连「生命历程五原则」（能动性原则的本体论版）与「惯习·场域·资本」（同题另一解：结构内化vs结构二重性）；张力边对「结构紧张/失范类型」——默顿式结构分析仍把结构当外在压力物，是吉登斯要拆除的残余。边界：二重性是本体论承诺而非可检验机制，Archer批它把批判时刻与例行混为一谈；对不平等的实质机制说得少——是语法不是历史。",links:[{t:"Polity《The Constitution of Society》",u:"https://www.politybooks.com/bookdetail?book_slug=the-constitution-of-society-outline-of-the-theory-of-structuration--9780745600079"}],aka:"吉登斯 结构化理论 社会的构成",domains:["meaning","relation"],lever:0},
// ── 现代性诊断 ──
{id:"beck_risk",cn:"风险社会/个体化",en:"Risk Society / Individualization",scholar:"Ulrich Beck",work:"《风险社会》Risikogesellschaft",year:"1986/1992",disc:"soc",school:"现代性诊断",core:"副作用成为主产品：风险按阶级落回地面；制度化人生退场→个体化为自己人生当CEO。",detail:"贝克1986年的《风险社会》给现代化诊断换了主语：工业社会的核心矛盾是财富分配，晚期现代的核心矛盾是风险分配——污染、核、金融危机这些「生产性风险」由现代化自己制造。他留下那句区分：「贫困是阶级的，烟雾是民主的」——但随即补刀：风险终究按阶级落回地面，富人买净化器、穷人吸尾气。配套的「个体化」命题：阶级、家庭、职业这些旧形态制度性退场，人被抛成自己人生的CEO——人生从「被给定的命运」变成「必须自己书写的传记」，而写砸的代价也个人化了。图谱中它以耦合边连「生命历程制度化」——「制度化个体主义」正是Kohli三段式人生的退场诊断；又接「流动现代性/有缺陷的消费者」（Bauman是同诊断的孪生）与「不稳定无产者」（precariat=被迫个体化者的下层形态）；谱系边放给「延迟成人/制度撤退」——Furstenberg的制度撤退即个体化的美国实证。边界：「风险民主化」对全球北方过拟合；个体化论低估阶级再生产的粘性——「自己书写人生」的权利本身就是阶级分配的。",links:[{t:"SAGE《Risk Society》",u:"https://us2.sagepub.com/en-us/nam/book/risk-society"}],aka:"贝克 风险社会 个体化 乌尔里希·贝克",domains:["meaning","work"],lever:0},
// ── 微观互动(续) ──
{id:"collins_irc",cn:"互动仪式链",en:"Interaction Ritual Chains",scholar:"Randall Collins",work:"Interaction Ritual Chains",year:"2004",disc:"soc",school:"微观互动",core:"每次面对面际遇是情感能量(EE)的充放电——成功仪式产出成员符号与自信，失败仪式排出羞耻。",detail:"柯林斯2004年把涂尔干的宗教仪式机制改造成微观社会学的通用引擎：任何面对面际遇（会议、饭局、课堂、面试）都是互动仪式——身体共在+相互觉察+共同焦点+情感连带四件齐备，就产出「情感能量」（EE：自信、热情、主动感）与群体符号（行话、徽章、默契）；失败的际遇则反向放电，产出疏离与羞耻。人生于是被读成「仪式链」：每次际遇给EE账户充值或扣款，人趋向高回报际遇、躲避放电际遇——所谓人格、志向、圈层忠诚，都是这条链的累积沉淀。这给阶级体验补上微观力学：精英俱乐部的放松感、底层遭遇的尴尬感，都是仪式收支表的读数。图谱中它以谱系边接「拟剧论/污名」（柯林斯明言是Goffman互动秩序的情感化推进）与「分工与有机团结」（涂尔干仪式机制的世俗化）；耦合边接「阶级隐痛」（羞耻=仪式失败的记账）与「道德-文化边界」（成员符号=边界的仪式产物）。边界：EE主要靠自报难客观测量；能解释一切际遇反而稀释预测力；线上共在时代的仪式形态仍在改写。",links:[{t:"Princeton UP《Interaction Ritual Chains》",u:"https://press.princeton.edu/books/paperback/9780691123899/interaction-ritual-chains"}],aka:"柯林斯 互动仪式 兰德尔·柯林斯",domains:["relation","meaning"],lever:0},
{id:"blau_exchange",cn:"社会交换/权力",en:"Exchange and Power in Social Life",scholar:"Peter M. Blau",work:"Exchange and Power in Social Life",year:"1964",disc:"soc",school:"微观互动",core:"宏观结构从微观交换涌现：恩惠→债务→依赖→权力——不平等起点是交换不对称。",detail:"布劳1964年的《社会生活中的交换与权力》要搭一座桥：微观互动怎么长出宏观结构？答案是交换——社会交往本质是利益与恩惠的互换，而交换天然不对称：我给你急需的，你就欠我；恩惠欠到还不起，就兑换成权力——服从、敬仰、决定权的让渡。于是权力不是位置属性而是交换失衡的沉淀物；但权力也要缴「合法性税」：只有被承认配得上的支配才沉淀为权威，否则只是强制。这个涌现逻辑给分层一个交易型解释：不平等的起点不在位置而在资源分布差造成的交换不对称。图谱中它以耦合边连「地位获得模型」——同一个布劳的两本书互为表里：一本问微观交换怎么长权力，一本问宏观位置怎么代际传递；又接「社会资本(创造人力资本)」——科尔曼的「义务与期望」正是布劳的恩惠债务存量；张力边对「拟剧论/污名」——交换论把人读成成本收益计算器，戈夫曼派说互动有礼仪式尊严不全是交易。边界：礼物、关爱、忠诚的「非计算」面向被压扁；对交换前的资源分布从哪来说得少——上游还得接阶级分析。",links:[{t:"Routledge《Exchange and Power in Social Life》",u:"https://www.routledge.com/Exchange-and-Power-in-Social-Life/Blau/p/book/9780887386282"}],aka:"布劳 社会交换 交换与权力",domains:["relation","money"],lever:0},
// ── 制度与组织 ──
{id:"dimaggio_powell",cn:"制度同构/铁笼重演",en:"Institutional Isomorphism",scholar:"DiMaggio & Powell",work:"The Iron Cage Revisited (ASR)",year:"1983",disc:"soc",school:"制度与组织",core:"组织趋同不靠效率靠同构三机制：强制(规制)+模仿(不确定)+规范(专业化)——第二波铁笼。",detail:"迪马久与鲍威尔1983年这篇ASR名篇追问一个悖论：组织若为效率而生，为什么同行业的组织越长越像？答案不是竞争选择而是「制度同构」三机制：强制性同构（法规、认证、资源依赖方要求你长那样）、模仿性同构（面对不确定性抄看起来成功的同行）、规范性同构（专业教育与职业共同体输出统一模板）。这把韦伯的铁笼重装上锁：理性化不再来自科层效率竞争，而来自制度环境的合法性压力——「长得像大家」本身就是入场券。这解释了大学、NGO、企业CSR部门在没人设计下的趋同。图谱中它以谱系边接「理性化/铁笼」——标题即明说是铁笼的重访：第二波理性化引擎从效率换成合法性；耦合边接「文凭社会」（专业化规范正是文凭通胀的制度面）、「有效维持不平等」（同构三机制是组织层「换维维持」的引擎之一）与「血统/精英招聘」（招聘的「文化匹配」=规范性同构的入口筛选）。边界：同构解释趋同解释不了分化（后续「制度逻辑」研究在补）；对同构压力下残余异质性与能动性端处理弱。",links:[{t:"ASR 1983 原文 (JSTOR DOI)",u:"https://doi.org/10.2307/2095101"}],aka:"迪马久 鲍威尔 制度同构 新制度主义",domains:["work"],lever:0},
{id:"abbott",cn:"职业系统/管辖权",en:"The System of Professions",scholar:"Andrew Abbott",work:"The System of Professions",year:"1988",disc:"soc",school:"制度与组织",core:"职业=对管辖权(jurisdiction)的争夺；抽象知识是管辖权货币；分析单位是职业间竞争而非单职业史。",detail:"阿伯特1988年的《职业系统》翻转职业研究的分析单位：别写「医生史」「律师史」这种单职业编年——职业是一个系统，关键动作是对「管辖权」的争夺：谁能把某类问题定义为自己的排他领地（医生抢下「治疗」、会计师抢下「审计」、精神病学家从神职手里抢「疯癫」），谁就拿到执照护城河与地位。核心货币是抽象知识：管辖权竞争靠的是知识的抽象度与可论证性而非技术的实用度——越抽象越能守住领地，也越能把活分包给低阶职业。这个系统视角直接续写社会封闭：管辖权就是专业化的封闭技术，职业间攻防（护理vs医生、律师vs会计师）是封闭机制的动态展开。图谱中它以谱系边接「社会封闭」——管辖权=排斥机制在职业场域的系统化；耦合边接「文凭社会」（文凭通胀=管辖权竞争的通膨面）与「制度同构/铁笼重演」（规范性同构的供应端正是职业共同体）。边界：模型高度适配执照/自由职业，对无执照职业与非西方体系（行会、单位制）需调整；对「顾客方」如何接受领地宣称的机制讲得薄。",links:[{t:"U Chicago Press《The System of Professions》",u:"https://press.uchicago.edu/ucp/books/book/chicago/S/bo5965590.html"}],aka:"阿伯特 职业系统 管辖权",stages:["s3","s4"],domains:["work"],lever:0},
// ── 流动经验学派(续) ──
{id:"sorokin",cn:"社会流动",en:"Social and Cultural Mobility",scholar:"Pitirim Sorokin",work:"Social Mobility / Social and Cultural Mobility",year:"1927",disc:"soc",school:"流动经验学派",core:"领域命名之作：垂直×水平流动坐标系+流动通道学(军队/教会/学校/婚姻)——流动研究的起点。",detail:"索罗金1927年的《社会流动》是这个领域的命名书：他把流动系统化为垂直（上/下）×水平（同行业换位）的坐标系，并首次盘点了社会的「流动通道」——军队、教会、学校、经济组织、家庭与婚姻，这些通道像泵站一样把人往上抽或往下沉。两条经验直觉影响深远：流动速率随开放度与动荡程度波动（革命、战争、工业化把闸门开大）；流动本身有心理代价（上升者的失调与断裂感）。后来文献的众多命题——教育作为通道、婚姻作为通道、流动者的心理成本——在这里已有雏形，只是尚无前统计时代的测量工具。图谱中它以谱系边连「地位获得模型」——索罗金的通道清单是Blau & Duncan路径分解的类目前身：通道学被翻成路径系数；又连「赞助/竞争流动」（Turner的通道二型是这份清单的制度精修）；耦合边接「跨阶层者」——Lubrano写的straddler心理代价正是索罗金「流动代价」的当代民族志。边界：材料杂、方法属前统计时代，作为概念框架而非实证范式存活；通道清单带着二十年代制度想象，平台经济与零工时代需重写。",links:[{t:"Internet Archive《Social and Cultural Mobility》(Free Press 1959)",u:"https://archive.org/details/socialculturalmo0000soro"}],aka:"索罗金 社会流动 垂直流动",domains:["mobility","work"],lever:0},
{id:"wisconsin",cn:"威斯康星模型",en:"Wisconsin Status Attainment Model",scholar:"Sewell, Haller & Portes",work:"The Educational and Early Occupational Attainment Process (ASR)",year:"1969",disc:"soc",school:"流动经验学派",core:"在父职-教育-职业链条中插入'重要他者'心理中介：期望(aspiration)是结构翻译成志向的兑换口。",detail:"休厄尔、哈勒与波蒂斯主导的威斯康星学派把Blau & Duncan的冷链条加温：在「父职→教育→初职」的硬路径中插入社会心理中介——「重要他者」（教师、父母、同伴的鼓励）如何形塑青少年的学业与职业期望，期望再驱动教育投入。1969年这篇ASR用威斯康星男生长追数据证明：家庭背景对最终地位的效应大半经由「被鼓励→形成高期望→更多投入」的心理链传导——结构不是直接压在人身上，是被翻译成志向再起作用。这把流动研究从位置决定论升级为「位置经由心灵」的中介模型，也是路径分析+纵贯设计的方法里程碑。图谱中它以谱系边接「地位获得模型」——OCG框架的社会心理化续章；耦合边接「志向持平」——MacLeod的民族志正是威斯康星期望链的底层版本：期望被现实可能集调平；张力边对「惯习·场域·资本」——期望作为可拆分中介 vs 惯习作为一体化生成器，仍是量化与民族志的方法论分界。边界：样本限威斯康星白人男性，性别与种族的期望机制另案；「重要他者」自报测量偏主观；模型仍是关联性而非因果识别。",links:[{t:"ASR 1969 原文 (JSTOR DOI)",u:"https://doi.org/10.2307/2092789"}],aka:"威斯康星模型 休厄尔 哈勒 地位获得",stages:["s2","s3"],domains:["mobility","work"],lever:0},
// ── 生命历程(续) ──
{id:"mannheim",cn:"世代位置/代的社会学",en:"The Problem of Generations",scholar:"Karl Mannheim",work:"Das Problem der Generationen",year:"1928",disc:"soc",school:"生命历程",core:"代=被同一历史时段相似经验'定位'的人群；关键期经验烙进集体底色——变迁靠人换不靠人变。",detail:"曼海姆1928年的《代的问题》把「代」从生物事实重写成社会位置：一代人不是同时出生的人，而是在同一历史时段以相似方式经历同一事件序列的人——世代位置跟阶级位置一样是结构给的。核心机制是关键期烙印：青年期遭遇的历史事件对人格塑性最大，所以同代人共享的不是年龄而是一套「自然化」的世界观底色；代内还分「世代单元」——同一事件对不同群体印记不同（同是六八年，保守学生与左翼学生是两个单元）。这解释了社会变迁为何不连续：不是人渐变而是人换——新世代带新底色进场、老世代带旧底色退场。图谱中它以谱系边连「年龄分层」——Riley的队列流把世代位置操作化为可追踪的人口结构；又连「生命历程五原则」——Elder的历史时空原则是世代位置的个体化（大萧条打中谁取决于当时几岁）；耦合边接「累积(不)优势」——队列内发散正是同一世代位置内部的再分层。边界：关键期窗口是理论推测非实证常数；加速时代「代」的边界模糊化（十年一代？）使概念需重新刻度。",links:[{t:"Palgrave章节 DOI",u:"https://doi.org/10.1007/978-1-349-24984-8_9"}],aka:"曼海姆 代的问题 世代",stages:["s2"],domains:["meaning"],lever:0},
{id:"clausen",cn:"美国人生/计划性能力",en:"American Lives",scholar:"John Clausen",work:"American Lives: Looking Back at the Children of the Great Depression",year:"1993",disc:"soc",school:"生命历程",core:"伯克利队列追踪六十年：'计划性能力'(自知+现实目标+坚持)是跨轨迹最稳预测器——能动性的可测量版。",detail:"克劳森1993年的《美国人生》做了生命历程研究里最奢侈的事：把伯克利大萧条队列重访到六十多岁，问的不是「你经历了什么」而是「什么样的人在什么轨道上」。贯穿五十年最强的预测器是「计划性能力」（planful competence）：自知（知道自己能做什么）、现实目标设定、坚持——具备者的学业、职业、婚姻全面更稳。更妙的是传导路径：青少年期的计划性能力→选择更好的教育/配偶/工作→中年资源更足→老年整合度更高——能动性不是魔法，而是一种可测的累积资产。这给Elder的能动性原则配上了心理测量学底盘：人确实建构生命历程，但建构工具本身在青少年期就已被分配。图谱中它以谱系边接「生命历程五原则」（能动性原则的个体化操作化）；耦合边接「累积(不)优势」（计划性能力=CAD的心理级引擎）与「主体-客体五阶」（Kegan的自我导向与计划性能力部分重叠）；张力边对「惯习·场域·资本」——能动性可测 vs 能动性即位置，布迪厄派会说这能力就是惯习换名。边界：伯克利队列偏小且时代特化；「计划性能力」与责任心等人格特质边界模糊；能力本身从哪来（家庭史机制）讲得薄。",links:[{t:"Publishers Weekly 书目 (Free Press/UC Press)",u:"http://www.publishersweekly.com/9780029055359"}],aka:"克劳森 美国人生 计划性能力",stages:["s2","s3","s4"],domains:["work","mobility","family"],lever:1},
{id:"mortimer",cn:"青少年工作/成人过渡",en:"Working and Growing Up in America",scholar:"Jeylan Mortimer",work:"Working and Growing Up in America",year:"2003",disc:"soc",school:"生命历程",core:"明尼苏达纵贯队列：青少年打工按强度×质量分诊——低强度指导性工作是过渡资产、高强度重复工是陷阱。",detail:"莫蒂默用明尼苏达青年发展研究（YDS，1988-2000千人级纵贯）重写了「青少年打工好不好」的争论：答案不是工不工，而是工多少、什么工——低强度（<20小时/周）、有指导性的工作是过渡资产：培养守时、责任感、职业探索与成人社会网；高强度（>20小时/周）、重复性工作挤占学业时间，是过渡陷阱。她的范式贡献是把「工作」从障碍改写成发展资源轴：青年工读经历是学校到成年之间的「半成人」过渡结构，过渡质量取决于这段连接是被设计的还是被消耗的。图谱中它以耦合边连「延迟成人/制度撤退」——低强度工作正是Furstenberg式缓冲期的微机制：有过渡垫的家庭让孩子慢慢到位；又接「生命历程五原则」（时机原则的直接实证：同一打工经历在15岁是训练、在25岁是死胡同）与「赞助/竞争流动」（有指导的工读是隐性赞助通道）。边界：YDS是美国中西部偏中产样本，对贫困与全球南方打工（非选择而是必需）结论需反转；工作质量依赖职业编码，测量粗糙。",links:[{t:"Harvard UP《Working and Growing Up in America》",u:"https://www.hup.harvard.edu/books/9780674016149"}],aka:"莫蒂默 青少年工作 成长于美国",stages:["s2","s3"],domains:["work","mobility"],lever:1},
// ── 福利体制 ──
{id:"esping",cn:"福利三世界",en:"Three Worlds of Welfare Capitalism",scholar:"Gøsta Esping-Andersen",work:"The Three Worlds of Welfare Capitalism",year:"1990",disc:"soc",school:"福利体制",core:"自由/保守-合作主义/社会民主三体制：去商品化×阶层化方式——人生风险谁扛由体制定。",detail:"埃斯平-安德森1990年的《福利资本主义的三个世界》把福利国家从「给多给少」改写为类型学：自由主义体制（美英加澳）靠市场+残补式救助、去商品化最低；保守-合作主义体制（德法意）靠职业保险+家庭主义、地位差被制度固化；社会民主体制（北欧）全民主义+高去商品化、人可不完全依赖市场而活。关键概念「去商品化」：福利的实质不是转移支付额度，而是人在多大程度上能不卖劳动力也活得像人。这把「人生风险谁扛」变成体制变量：失业、病老、生育、转轨的成本在三个世界里分别由市场、家庭、国家承接——同一个25岁，在哥本哈根与底特律的结构位置根本不同。图谱中它以谱系边连「生命历程制度化」——Kohli的三段式人生正是福利体制的德国版展开；耦合边接「成年转变推迟」（南欧latest-late=保守-家庭主义体制的转轨输出）、「延迟成人/制度撤退」（美国=自由体制的极端化）与「不稳定无产者」（precariat在自由体制最厚）。边界：三型是90年代理想型，东亚与南欧混合体制需补型；女性视角批评（去商品化默认男性工人、照护劳动隐形）催生了后续修正浪潮。",links:[{t:"Princeton UP《The Three Worlds of Welfare Capitalism》",u:"https://press.princeton.edu/books/paperback/9780691028576/the-three-worlds-of-welfare-capitalism"}],aka:"埃斯平-安德森 福利三世界 去商品化",domains:["work","family","money"],lever:0}
);
